const QUIP=L(`
أوحش اسم ممكن تسمّي بيه محل كشري
أول جملة هتقولها لو قابلت كائن فضائي
أغرب حاجة ممكن تلاقيها في شنطة أمك
اسم فيلم مصري جديد بطولة الشلة دي
أسوأ حاجة تقولها في أول يوم شغل
الرسالة اللي هتبعتها للجروب لو كسبت مليون
أسوأ هدية عيد ميلاد ممكن تجيبها لحد
إعلان لمنتج محدش محتاجه
عنوان خبر في الجرايد عن آخر خروجة لينا
أوحش اسم لمطعم سمك
لو القطط اتكلمت، أول حاجة هتقولها إيه؟
اسم جديد للإنترنت
حاجة متقولهاش لحماتك أبدًا
أسوأ نصيحة لحد عنده امتحان بكرة
اختراع جديد يحل مشكلة الزحمة
أغرب سبب تتأخر بيه على الشغل
الحاجة الوحيدة اللي هتاخدها معاك على جزيرة مهجورة (غير الموبايل)
اسم أغنية مهرجانات جديدة
إيه اللي بيحصل جوه التلاجة لما بنقفلها؟
أوحش وظيفة في العالم
لو الكشري بقى بني آدم، شخصيته هتبقى إزاي؟
أسوأ جملة تقولها في خطوبتك
مادة المفروض المدارس تدرّسها
السبب الحقيقي إن الكهربا بتقطع
أسوأ جملة تتكتب في كارت عيد ميلاد
أبلكيشن جديد محدش هينزّله
أول قرار هتاخده لو بقيت رئيس يوم واحد
الكلب بيفكر في إيه وهو باصصلك؟
اسم برنامج توك شو عن الشلة
أوحش حاجة ممكن تحصل في الأسانسير
لو فيه أولمبياد للكسل، الرياضة الأساسية هتبقى إيه؟
تحذير مكتوب على علبة أكل غريب
جملة متتقالش في عزومة
أغرب طلب ممكن تطلبه من الدليفري
اسم علمي جديد لمرض الكسل
المدرس بيكتب إيه في الكراسة لما يزهق؟
شعار حملة انتخابات في الشلة
أوحش جملة تقولها لمديرك
لو الموبايل بيحس، هيشتكي من إيه؟
قانون جديد لازم يتضاف للكورة
السبب الحقيقي اللي خلّى الديناصورات تنقرض
تحذير لأي حد عايز يصاحب الشلة دي
أوحش مكان تعمل فيه عيد ميلاد
الميكانيكي بيقول إيه لما يبص على عربيتك؟
اسم برفان جديد بريحة غريبة
إيه اللي بيحصل لما تقول "خمس دقايق كمان" وانت نايم؟
أغرب سؤال ممكن يتسأل في انترفيو
بداية جواب رومانسي فاشل
رسالة من نفسك وانت عندك 80 سنة
عنوان كتاب عن حياتك
أحسن رد على سؤال "انت فين؟"
أوحش اسم لمحل حلاقة
حاجة لو عملتها في فرح هيطردوك
العصافير بتتكلم في إيه وهي واقفة على السلك؟
لعبة جديدة للقعدات
جملة تخلّص أي خناقة
مشروع هيخسّرك كل فلوسك
آخر رسالة في جروب العيلة قبل ما يتقفل
أوحش طعم آيس كريم
حاجة الشلة هتفتكرها بعد 20 سنة من النهارده
`);

