const PUN=L(`
اغسل الكوبايات بتاعة القعدة.
اعمل شاي للشلة كلها.
اتكلم بالفصحى لحد اللعبة الجاية.
اعمل 20 ضغط.
غنّي أغنية يختارها الكسبان.
قلّد حد في الشلة لحد ما يعرفوه.
ارقص دقيقة كاملة.
الكسبان يختارلك صورة بروفايل لمدة ساعة.
اقعد على الأرض في اللعبة الجاية.
انزل ستوري تشكر فيه الكسبان.
اتكلم بلكنة خواجة لحد اللعبة الجاية.
ادفع حق الحاجة الساقعة الجاية.
قول حاجة حلوة في كل واحد في الشلة.
خلّي الكسبان يكتب كلمة على إيدك.
اقف على رجل واحدة لمدة دقيقة.
ابعت فويس لجروب الشلة تقول فيه "أنا خسرت ومش زعلان".
ابدأ كل جملة بـ "يا جماعة" لحد اللعبة الجاية.
اعمل إعلان عن الكسبان كأنه منتج.
البس الجاكيت بالمقلوب لحد اللعبة الجاية.
رتّب المكان بعد القعدة.
قدّم نتيجة اللعبة كأنك مذيع نشرة.
كل واحد يقول رأيه في لبسك وانت متردش.
اعمل 30 نطة.
قول "أنا أوحش لاعب" بعد كل دور في اللعبة الجاية.
اعمل صوت حيوان يختاره الكسبان كل ما حد يقول اسمك.
ألّف بيتين شعر عن الكسبان وقولهم.
خلّي الكسبان يختار خلفية موبايلك لمدة يوم.
اقعد دقيقة من غير ما تضحك والكل بيحاول يضحّكك.
اتصور سيلفي بأغرب وش وابعته للجروب.
امشي زي الروبوت لحد اللعبة الجاية.
قول اسم الكسبان بخمس طرق مختلفة.
قوم سلّم على الكسبان كأنه ملك.
اعزم الشلة على حاجة حلوة المرة الجاية.
اتكلم بصوت هامس لحد اللعبة الجاية.
احكي أحرج موقف حصلك.
مثّل إنك بتقدّم برنامج طبخ وانت بتعمل ساندوتش وهمي.
`);

