/* ---------- language ---------- */
const AR={TRUTH,DARE,NEVER,MOST,RATHER,QUIP,SPY,KNOW,DRAW,TABOO,QUIZ,PUN};
const App={page:'home',mode:null,S:null,host:false,myPeer:null,me:null,nm:LS.get('shilla.nm',''),off:0,code:'',lost:false,pun:LS.get('shilla.pun',[]),last:'',pen:'#1b1433',
 lang:LS.get('shilla.lang',null)||'ar',mute:LS.get('shilla.mute',false),roomOK:typeof Peer==='function'};
const EL=()=>App.lang==='en';
const A=(ar,en)=>EL()?en:ar;
const B=k=>(EL()?EN:AR)[k];
function applyLang(){document.documentElement.lang=App.lang;document.documentElement.dir=EL()?'ltr':'rtl';document.title=A('الشلّة','Shilla')}
applyLang();

/* ---------- sound + confetti ---------- */
const SFX={ctx:null,
 init(){if(this.ctx||App.mute)return;try{this.ctx=new (window.AudioContext||window.webkitAudioContext)()}catch(e){}},
 tone(f,d,type='sine',v=.14,when=0){if(App.mute||!this.ctx)return;try{const c=this.ctx,t=c.currentTime+when,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+d+.02)}catch(e){}},
 play(n){if(App.mute)return;this.init();if(!this.ctx)return;if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>{});
  const T=(f,d,ty,v,w)=>this.tone(f,d,ty,v,w);
  if(n==='tap')T(620,.06,'triangle',.08);
  else if(n==='pop')T(520,.09,'triangle',.12),T(780,.1,'triangle',.1,.06);
  else if(n==='tick')T(1000,.05,'square',.05);
  else if(n==='buzz')T(140,.35,'sawtooth',.12);
  else if(n==='ding')T(880,.25,'sine',.15),T(1320,.35,'sine',.1,.08);
  else if(n==='win')[523,659,784,1046].forEach((f,i)=>T(f,.28,'triangle',.13,i*.12));
  else if(n==='spin')for(let i=0;i<18;i++)T(700+rint(200),.04,'square',.04,i*(.05+i*.012));
  else if(n==='coin')T(988,.08,'square',.07),T(1319,.25,'square',.07,.08);
  else if(n==='sad')[392,370,349,311].forEach((f,i)=>T(f,i===3?.7:.3,'sawtooth',.07,i*.3));
  else if(n==='turn')T(660,.12,'sine',.14),T(990,.2,'sine',.12,.1);
  else if(n==='whoosh')this.noise(.35,300,2400,.09);
  else if(n==='boom'){this.noise(1.1,900,50,.5);T(55,.9,'sine',.4)}
  else if(n==='drum'){for(let i=0;i<16;i++)this.noise(.06,180,120,.18,i*(.075-i*.002))}
  else if(n==='cheer'){for(let i=0;i<5;i++)this.noise(.5,900+rint(900),1500+rint(900),.06,i*.12)}},
 noise(d,f0,f1,v=.1,when=0){if(App.mute||!this.ctx)return;try{const c=this.ctx,t=c.currentTime+when,n=Math.floor(c.sampleRate*d),b=c.createBuffer(1,n,c.sampleRate),ch=b.getChannelData(0);for(let i=0;i<n;i++)ch[i]=Math.random()*2-1;
  const s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=b;f.type='bandpass';f.Q.value=1.2;f.frequency.setValueAtTime(f0,t);f.frequency.exponentialRampToValueAtTime(Math.max(30,f1),t+d);g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.0001,t+d);s.connect(f);f.connect(g);g.connect(c.destination);s.start(t);s.stop(t+d+.02)}catch(e){}}};
const buzz=p=>{try{if(!App.mute&&navigator.vibrate)navigator.vibrate(p)}catch(e){}};
const AV=['🦁','🐯','🐻','🐼','🐨','🐸','🐵','🦊','🐶','🐱','🐰','🐹','🐷','🐮','🐔','🐧','🦄','🐙','🦉','🐢','🐬','🦖','🐝','🦋','👽','🤖','👻','🎃'];
function confetti(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;let cv=$('#fx');if(!cv){cv=document.createElement('canvas');cv.id='fx';document.body.appendChild(cv)}
 const d=window.devicePixelRatio||1,W=innerWidth,H=innerHeight;cv.width=W*d;cv.height=H*d;const x=cv.getContext&&cv.getContext('2d');if(!x)return;x.scale(d,d);
 const ps=range(140).map(()=>({x:W/2+(Math.random()-.5)*W*.4,y:H*.35,vx:(Math.random()-.5)*11,vy:-Math.random()*12-4,s:5+Math.random()*7,r:Math.random()*6,vr:(Math.random()-.5)*.3,c:COLS[rint(8)]}));
 const t0=performance.now();(function f(t){const e=t-t0;x.clearRect(0,0,W,H);for(const p of ps){p.vy+=.35;p.x+=p.vx;p.y+=p.vy;p.r+=p.vr;x.save();x.translate(p.x,p.y);x.rotate(p.r);x.fillStyle=p.c;x.fillRect(-p.s/2,-p.s/3,p.s,p.s*.66);x.restore()}if(e<2600)requestAnimationFrame(f);else x.clearRect(0,0,W,H)})(t0)}

/* ---------- helpers ---------- */
const P=id=>App.S&&App.S.pl.find(p=>p.id===id);
const nm=id=>(P(id)||{}).n||A('حد','someone');
const ids=()=>App.S.pl.map(p=>p.id);
const TCOL=['#ff4f9a','#2fe0cf'];
const tName=t=>t===0?A('الفريق الوردي','Pink team'):A('الفريق التركوازي','Teal team');
const chip=(id,x='')=>{const p=P(id);const tm=App.S&&App.S.tmOn&&p&&p.t!=null?` data-t="${p.t}"`:'';return `<span class="pc" style="--c:${p?p.c:'#9a90c0'}"${tm}>${p&&p.e?`<i class="av">${p.e}</i>`:''}${esc(p?p.n:'؟')}${x}</span>`};
const J=o=>esc(JSON.stringify(o));
const btn=(l,a,c='',dis)=>`<button type="button" class="b ${c}" data-j="${J(a)}"${dis?' disabled':''}>${l}</button>`;
const ub=(l,u,x='',c='')=>`<button type="button" class="b ${c}" data-u="${u}" data-x="${esc(x)}">${l}</button>`;
const pbtn=(id,a)=>{const p=P(id);return `<button type="button" class="b pl" style="--c:${p?p.c:'#888'}" data-j="${J(a)}">${p&&p.e?p.e+' ':''}${esc(p?p.n:'؟')}</button>`};
const card=(tag,txt,c,extra='')=>`<article class="qc ${c}"><span class="tag">${tag}</span><p>${esc(txt)}</p>${extra}</article>`;
const tmr=g=>g.te?`<div class="tmr" data-te="${g.te}"><span>⏱</span><b>--</b></div>`:'';
const wait=t=>`<div class="wt"><span class="dots"><i></i><i></i><i></i></span><span>${t}</span></div>`;
const setT=(g,ms)=>{g.te=Date.now()+ms;g.tf=0};
const goT=(g,ms)=>{g.cd=Date.now()+3200;g.te=g.cd+ms;g.tf=0};
const cdown=g=>g.cd&&Date.now()+offNow()<g.cd?`<div class="cdown" data-cd="${g.cd}"><b>3</b></div>`:'';
const coll=(g,k,need,s=1)=>{g.c={k,need,got:{},s}};
const tally=got=>{const t={};for(const id in got){const v=got[id];if(v==null||v==='-')continue;t[v]=(t[v]||0)+1}return t};
const tops=t=>{const vals=Object.values(t);const m=vals.length?Math.max(...vals):0;return m?Object.keys(t).filter(k=>t[k]===m):[]};
const curOf=g=>g.ord[g.t%g.ord.length];
const bar=(lbl,n,tot,c)=>`<div class="bar"><div class="bl">${lbl}</div><div class="bt"><i style="width:${Math.round(n/tot*100)}%;--c:${c||'#ffd23f'}"></i></div><b>${n}</b></div>`;
const nextBtn=(g,X,last)=>X.C?btn(last?A('النتيجة 🏁','Results 🏁'):A('التالي ⬅','Next ➡'),{t:'next'},'pri'):wait(A('المضيف هيكمّل...','The host will continue...'));
const toast=t=>{const el=$('#toast');if(!el)return;el.textContent=t;el.classList.add('on');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.remove('on'),2600)};
const ABCD=i=>EL()?'ABCD'[i]:'أبجد'[i];
const order=()=>{const S=App.S,I=ids();if(!S.tmOn)return I;const a=I.filter(i=>P(i).t===0),b=I.filter(i=>P(i).t===1),o=[];for(let i=0;i<Math.max(a.length,b.length);i++){if(a[i])o.push(a[i]);if(b[i])o.push(b[i])}return o};

function curtain(pid,key,txt){return `<div class="curt"><div class="big">📱</div><h2>${A('سلّم الموبايل لـ','Pass the phone to')} ${chip(pid)}</h2><p>${txt||A('الباقيين ميبصّوش 🙈','No peeking, everyone else 🙈')}</p>${ub(A('أنا ','I\'m ')+esc(nm(pid))+A('، وريني',', show me'),'reveal',key,'pri xl')}</div>`}
function waitBox(c,X,t){return `<div class="wb"><h3>${t||A('مستنيين الباقيين...','Waiting for the others...')}</h3><div class="chips">${c.need.map(id=>chip(id,id in c.got?' ✓':' …')).join('')}</div>${X.C?btn(A('كمّلوا من غير اللي فاضلين ⏭','Continue without them ⏭'),{t:'skipc'},'ghost sm'):''}</div>`}
const inInput=(g,X)=>!X.L&&X.me&&g.c&&g.c.need.includes(X.me)&&!(X.me in g.c.got)&&ui.sent!==g.c.k;
function cv(g,X,inp,o={}){const c=g.c;if(!c)return '';
 if(X.L){const pid=c.need.find(id=>!(id in c.got));if(!pid)return '';
  if(c.s&&ui.cur!==c.k+'|'+pid)return curtain(pid,c.k+'|'+pid,o.ct);
  return `<div class="turn">${A('دور','Turn:')} ${chip(pid)}</div>`+inp(pid)}
 if(inInput(g,X))return inp(X.me);
 return waitBox(c,X,o.wt)}


const G={};
const CATS=()=>[{n:A('كلام وصراحة','Talk & truth'),c:'pink'},{n:A('تصويت','Voting'),c:'sun'},{n:A('كشف وتخمين','Bluff & guess'),c:'cyan'},{n:A('سرعة وذكاء','Speed & smarts'),c:'orng'}];
const LVN=()=>[[A('عادي','Normal'),'🙂'],[A('محرج','Awkward'),'😳'],[A('محرج جدًا','Very awkward'),'🫣'],[A('فضيحة','Scandal'),'🔥']];
const LVD=()=>[[A('سهل','Easy'),'🙂'],[A('متوسط','Medium'),'🤔'],[A('صعب','Hard'),'🧠']];
const LVOF=d=>d.lv==='N'?LVN():d.lv==='D'?LVD():null;
const head=(t,extra='')=>`<div class="tb"><small>${t}</small>${extra}</div>`;
const ofN=(a,b)=>A(`${a} من ${b}`,`${a} of ${b}`);
const turnHead=(g,cur,lbl)=>`<div class="tb">${chip(cur)}<small>${lbl||A('دور','Turn')} ${ofN(g.n+1,g.tot)}</small></div>`;
const nAr=s=>String(s||'').toLowerCase().replace(/[ً-ْـ]/g,'').replace(/[أإآ]/g,'ا').replace(/ة/g,'ه').replace(/ى/g,'ي').replace(/[^\p{L}\p{N}]+/gu,'').replace(/^ال(?=..)/,'').replace(/^the(?=...)/,'');

/* ===== Truth or dare ===== */
G.td={e:'🎭',cat:0,min:2,lv:'N',R:3,Rmax:10,
 n:()=>A('صراحة ولا جرأة','Truth or dare'),Ru:()=>A('اللفّات','rounds'),
 d:()=>A('اعترف بصراحة أو نفّذ التحدي','Confess or take the dare'),
 h:()=>A('كل واحد في دوره يختار: صراحة ويجاوب على سؤال بصراحة، ولا جرأة وينفّذ تحدي في دقيقة. اللي يعملها ياخد نقطة، واللي يهرب يتخصم منه نقطة.','On your turn pick truth and answer honestly, or dare and do the challenge within a minute. Doing it earns a point; chickening out loses one.'),
 start(S,su){const ord=order();return{ord,t:0,n:0,tot:ord.length*su.R,ph:'p',dk:{t:shuf(range(TRUTH[su.lvl].length)),d:shuf(range(DARE[su.lvl].length))},pi:{t:0,d:0}}},
 nx(g,k){const d=g.dk[k];return d[g.pi[k]++%d.length]},
 act(g,a,pid,C,S){const cur=curOf(g);if(!(C||pid===cur))return false;
  if(a.t==='pick'&&g.ph==='p'&&(a.k==='t'||a.k==='d')){g.k=a.k;g.q=this.nx(g,a.k);g.ph='c';g.sw=0;if(a.k==='d')setT(g,60000);else g.te=0;return}
  if(a.t==='swap'&&g.ph==='c'&&!g.sw){g.q=this.nx(g,g.k);g.sw=1;return}
  if(a.t==='done'&&g.ph==='c'){g.sc[cur]+=a.ok?1:-1;g.n++;g.te=0;if(g.n>=g.tot){finish(S);return}g.t++;g.ph='p';return}
  return false},
 view(g,X){const cur=curOf(g),can=X.C||X.me===cur,h=turnHead(g,cur);
  if(g.ph==='p')return h+(can?`<p class="hint">${A('اختار يا','Pick,')} ${esc(nm(cur))}</p><div class="duo">${btn('<span>💬</span>'+A('صراحة','Truth'),{t:'pick',k:'t'},'big pink')}${btn('<span>🔥</span>'+A('جرأة','Dare'),{t:'pick',k:'d'},'big sun')}</div>`:wait(esc(nm(cur))+A(' بيختار...',' is choosing...')));
  const tx=B(g.k==='t'?'TRUTH':'DARE')[g.lvl][g.q];
  return h+card(g.k==='t'?A('صراحة 💬','Truth 💬'):A('جرأة 🔥','Dare 🔥'),tx,g.k==='t'?'pink':'sun')+tmr(g)+(can?`<div class="row">${btn(A('عملها ✅ +1','Done ✅ +1'),{t:'done',ok:1},'ok')}${btn(A('هرب 🏃 −1','Chickened out 🏃 −1'),{t:'done',ok:0},'bad')}</div>${g.sw?'':btn(A('غيّر السؤال 🔄','Change it 🔄'),{t:'swap'},'ghost sm')}`:'')}
};

/* ===== Never have I ever ===== */
G.nv={e:'🙋',cat:0,min:3,lv:'N',R:10,Rmax:35,low:1,
 n:()=>A('أنا عمري ما','Never have I ever'),Ru:()=>A('الجمل','statements'),
 d:()=>A('اللي عملها ياخد نقطة فضيحة','Did it? That\'s a scandal point'),
 h:()=>A('تظهر جملة تبدأ بـ «أنا عمري ما». اللي عمل الحاجة دي قبل كده ياخد نقطة فضيحة. في الآخر اللي فضايحه أقل هو الكسبان، واللي فضايحه أكتر عليه العقاب.','A "Never have I ever" statement appears. Anyone who has done it gets a scandal point. Fewest scandals wins; the most scandalous takes the punishment.'),
 start(S,su){const g={dk:shuf(range(NEVER[su.lvl].length)),n:0,R:su.R};this.beg(g);return g},
 beg(g){g.q=g.dk[g.n%g.dk.length];g.ph='q';g.did=[];coll(g,'n'+g.n,ids(),0)},
 done(g,c){g.did=Object.keys(c.got).filter(id=>c.got[id]===1);g.did.forEach(id=>{if(id in g.sc)g.sc[id]++});g.ph='r'},
 act(g,a,pid,C,S){
  if(a.t==='nvl'&&C&&g.c&&Array.isArray(a.did)){const c=g.c;c.need.forEach(id=>c.got[id]=a.did.includes(id)?1:0);g.c=null;this.done(g,c);return}
  if(a.t==='next'&&C&&g.ph==='r'){g.n++;if(g.n>=g.R){finish(S);return}this.beg(g);return}
  return false},
 view(g,X){const h=head(A('جملة ','Statement ')+ofN(g.n+1,g.R))+card(A('اعتراف 🙋','Confess 🙋'),B('NEVER')[g.lvl][g.q],'pink');
  if(g.ph==='q'){
   if(X.L){const sel=ui.sel||(ui.sel=[]);return h+`<p class="hint">${A('دوسوا على اسم كل واحد عملها','Tap everyone who has done it')}</p><div class="chips pick">${ids().map(id=>`<button type="button" class="pc tg${sel.includes(id)?' on':''}" style="--c:${P(id).c}" data-u="nvt" data-x="${id}">${esc(nm(id))}${sel.includes(id)?' 🙋':''}</button>`).join('')}</div>${btn(sel.length?A('تمام، كمّل ✅','Done ✅'):A('محدش عملها 😇','Nobody did 😇'),{t:'nvl',did:sel},'pri')}`}
   return h+cv(g,X,()=>`<div class="duo">${btn('<span>🙋</span>'+A('عملتها','I have'),{t:'sub',k:g.c.k,v:1},'big bad')}${btn('<span>😇</span>'+A('عمري ما','Never'),{t:'sub',k:g.c.k,v:0},'big ok')}</div>`,{wt:A('مستنيين الكل يعترف...','Waiting for everyone to confess...')})}
  return h+`<div class="rv">${g.did.length?`<h3>${A('اللي عملوها 🙋','They have 🙋')}</h3><div class="chips">${g.did.map(id=>chip(id)).join('')}</div>`:`<h3>${A('محدش عملها، شلة محترمة 😇','Nobody! Such a decent group 😇')}</h3>`}</div>`+nextBtn(g,X,g.n+1>=g.R)}
};

/* ===== Two truths and a lie ===== */
G.tt={e:'🤥',cat:0,min:3,R:1,Rmax:3,
 n:()=>A('اتنين صح وواحدة كدب','Two truths & a lie'),Ru:()=>A('اللفّات','rounds'),
 d:()=>A('اكتب 3 حاجات واحدة منهم كدب','Write 3 facts, one is a lie'),
 h:()=>A('كل واحد في دوره يكتب 3 حاجات عن نفسه: اتنين حقيقيين وواحدة كدب. الباقيين يخمّنوا الكدبة. اللي يعرفها ياخد نقطة، والكاتب ياخد نقطة عن كل واحد اتضحك عليه.','On your turn write 3 things about yourself: two true, one lie. Everyone guesses the lie. Right guesses earn a point; the writer earns a point for each person fooled.'),
 start(S,su){const g={ord:order(),t:0,n:0,tot:ids().length*su.R};this.beg(g);return g},
 beg(g){g.ph='w';g.st=null;g.gs=null;coll(g,'w'+g.n,[curOf(g)])},
 adv(g,S){g.n++;g.t++;if(g.n>=g.tot){finish(S);return}this.beg(g)},
 done(g,c,S){const cur=curOf(g);
  if(c.k[0]==='w'){const v=c.got[cur];if(!v||!Array.isArray(v.s)||v.s.length!==3){this.adv(g,S);return}g.st=v.s.map(x=>clean(x,70)||'…');g.lie=[0,1,2].includes(v.l)?v.l:0;g.ph='g';coll(g,'g'+g.n,g.ord.filter(i=>i!==cur));return}
  g.gs=c.got;let ok=0;for(const id in c.got)if(c.got[id]===g.lie){g.sc[id]++;ok++}g.sc[cur]+=Object.keys(c.got).length-ok;g.ph='r'},
 act(g,a,pid,C,S){if(a.t==='next'&&C&&g.ph==='r'){this.adv(g,S);return}return false},
 view(g,X){const cur=curOf(g),h=turnHead(g,cur);
  if(g.ph==='w')return h+cv(g,X,pid=>`<p class="hint">${A('اكتب 3 حاجات عنك، واختار أنهي واحدة كدب 🤫','Write 3 things about you and mark the lie 🤫')}</p><div class="form">${[0,1,2].map(i=>`<div class="fl"><input id="tt${i}" maxlength="70" autocomplete="off" placeholder="${A('حاجة رقم ','Fact #')}${i+1}"><label class="lie"><input type="radio" name="ttl" id="ttr${i}" value="${i}"> ${A('دي الكدبة','This is the lie')}</label></div>`).join('')}</div>${ub(A('ابعت 📨','Send 📨'),'ttsub',pid,'pri')}`,{ct:A('اكتب حاجاتك ومحدش يبص 🤫','Write yours, no peeking 🤫'),wt:esc(nm(cur))+A(' بيكتب...',' is writing...')});
  if(g.ph==='g')return h+`<p class="hint">${A('أنهي واحدة كدب؟','Which one is the lie?')}</p>`+cv(g,X,pid=>`<div class="opts">${g.st.map((s,i)=>btn(`<em>${i+1}</em><span>${esc(s)}</span>`,{t:'sub',k:g.c.k,v:i,as:pid},'opt')).join('')}</div>`,{wt:A('مستنيين التخمينات...','Waiting for guesses...')})+(!X.L&&!inInput(g,X)?`<div class="opts ro">${g.st.map((s,i)=>`<div class="optr"><em>${i+1}</em><span>${esc(s)}</span></div>`).join('')}</div>`:'');
  return h+`<div class="opts ro">${g.st.map((s,i)=>`<div class="optr${i===g.lie?' lie':''}"><em>${i===g.lie?'🤥':'✓'}</em><span>${esc(s)}</span><div class="chips">${Object.keys(g.gs||{}).filter(id=>g.gs[id]===i).map(id=>chip(id)).join('')}</div></div>`).join('')}</div>`+nextBtn(g,X,g.n+1>=g.tot)}
};

/* ===== Fortune wheel ===== */
const FWT=['t','d','m','r','t','d','g','s'];
const FWE={t:'💬',d:'🔥',m:'👉',r:'⚖️',g:'🎁',s:'🔁'};
G.fw={e:'🎡',cat:0,min:2,lv:'N',R:10,Rmax:40,
 n:()=>A('عجلة الحظ','Wheel of fortune'),Ru:()=>A('اللفّات','spins'),
 d:()=>A('العجلة تختار مين وتختار إيه','The wheel picks who and what'),
 h:()=>A('العجلة بتلف وبتختار حد عشوائي وبتطلعله حاجة: صراحة، جرأة، مين فينا، لو خيروك، هدية نقطتين ببلاش، أو «دبّس حد» يعمل التحدي بداله. اللي يعمل ياخد نقطة واللي يهرب يتخصم نقطة.','The wheel spins, picks a random player and gives them something: truth, dare, who\'s most likely, would you rather, a free 2-point gift, or "pass it on" to make someone else take a dare. Doing it earns a point; skipping loses one.'),
 start(S,su){return{n:0,R:su.R,ph:'sp',p:null,at:0,dk:{t:shuf(range(TRUTH[su.lvl].length)),d:shuf(range(DARE[su.lvl].length)),m:shuf(range(MOST[su.lvl].length)),r:shuf(range(RATHER[su.lvl].length))},pi:{t:0,d:0,m:0,r:0},last:[]}},
 act(g,a,pid,C,S){
  if(a.t==='fspin'&&C&&g.ph==='sp'){const I=ids().filter(i=>!g.last.includes(i));const who=(I.length?I:ids())[rint((I.length?I:ids()).length)];g.who=who;g.last=[who,...g.last].slice(0,Math.min(3,ids().length-1));g.p=rint(8);g.ty=FWT[g.p];g.at=Date.now();
   const k=g.ty==='s'?'d':g.ty;if(g.dk[k]){const d=g.dk[k];g.q=d[g.pi[k]++%d.length]}g.to=null;g.ph='sh';if(g.ty==='g'&&g.who in g.sc)g.sc[g.who]+=2;return}
  if(a.t==='fto'&&g.ph==='sh'&&g.ty==='s'&&!g.to&&(C||pid===g.who)&&a.w in g.sc&&a.w!==g.who){g.to=a.w;return}
  if(a.t==='fdone'&&g.ph==='sh'&&(C||pid===g.who||pid===g.to)){const tgt=g.ty==='s'?g.to:g.who;if(g.ty!=='g'&&tgt&&tgt in g.sc)g.sc[tgt]+=a.ok?1:-1;g.n++;if(g.n>=g.R){finish(S);return}g.ph='sp';g.p=null;return}
  return false},
 view(g,X){const h=head(A('لفّة ','Spin ')+ofN(g.n+1,g.R));const seg=45,el=g.at?Date.now()+offNow()-g.at:1e9,done=g.ph==='sh'&&el>4300,ang=g.p!=null?360*6-(g.p+.5)*seg:0;
  const wheel=`<div class="wheel"><div class="ptr"></div><div class="wd" data-ang="${ang}" data-at="${g.at}">${FWT.map((t,i)=>`<span style="--r:${(i+.5)*seg}deg">${FWE[t]}</span>`).join('')}</div><div class="hub">🎡</div></div>`;
  if(g.ph==='sp')return h+wheel+(X.C?btn(A('لفّ العجلة! 🎡','Spin! 🎡'),{t:'fspin'},'pri xl'):wait(A('المضيف هيلفّ...','The host will spin...')));
  if(!done)return h+wheel+`<p class="hint">${A('العجلة بتلف...','Spinning...')}</p>`;
  const who=g.who,can=X.C||X.me===who,lv=g.lvl;let body='';
  if(g.ty==='t')body=card(A('صراحة 💬','Truth 💬'),B('TRUTH')[lv][g.q],'pink');
  else if(g.ty==='d')body=card(A('جرأة 🔥','Dare 🔥'),B('DARE')[lv][g.q],'sun');
  else if(g.ty==='m')body=card(A('مين فينا؟ 👉','Who\'s most likely? 👉'),B('MOST')[lv][g.q],'sun',`<small>${A('الكل يشاور على حد في نفس اللحظة، و','Everyone points at once, and ')}${esc(nm(who))}${A(' يقول مين خد أكتر',' says who got the most')}</small>`);
  else if(g.ty==='r'){const Q=B('RATHER')[lv][g.q];body=card(A('لو خيروك ⚖️','Would you rather ⚖️'),Q[0]+A(' ولا ',' or ')+Q[1],'cyan',`<small>${A('اختار واشرح ليه','Pick one and explain why')}</small>`)}
  else if(g.ty==='g')body=`<div class="rv"><h3>🎁 ${A('هدية! نقطتين ببلاش لـ','Gift! 2 free points for')} ${chip(who)}</h3></div>`;
  else{if(!g.to)body=`<div class="rv"><h3>🔁 ${A('دبّس حد!','Pass it on!')}</h3><p>${esc(nm(who))} ${A('يختار حد يعمل جرأة بداله','picks someone to take a dare instead')}</p></div>`+(can?`<div class="grid2">${ids().filter(i=>i!==who).map(id=>pbtn(id,{t:'fto',w:id})).join('')}</div>`:'');
   else body=`<div class="tb">${chip(g.to)}<small>${A('اتدبّس 😈','got picked 😈')}</small></div>`+card(A('جرأة 🔥','Dare 🔥'),B('DARE')[lv][g.q],'sun')}
  const tgt=g.ty==='s'?g.to:who;const canD=X.C||X.me===who||(g.to&&X.me===g.to);
  const ctl=g.ty==='g'?(X.C?btn(A('اللفّة الجاية ⬅','Next spin ➡'),{t:'fdone',ok:1},'pri'):''):(tgt&&canD?`<div class="row">${btn(A('عملها ✅ +1','Done ✅ +1'),{t:'fdone',ok:1},'ok')}${btn(A('هرب 🏃 −1','Skipped 🏃 −1'),{t:'fdone',ok:0},'bad')}</div>`:'');
  return h+`<div class="tb">${chip(who)}<small>${A('العجلة اختارتك!','The wheel picked you!')}</small></div>`+body+ctl}
};

/* ===== Who's most likely ===== */
G.ml={e:'👉',cat:1,min:3,lv:'N',R:10,Rmax:30,
 n:()=>A('مين فينا؟','Who\'s most likely?'),Ru:()=>A('الأسئلة','questions'),
 d:()=>A('صوّتوا سرّي على مين أكتر واحد','Vote secretly for who fits best'),
 h:()=>A('يظهر سؤال زي «مين فينا أكتر واحد بيتأخر؟» وكل واحد يصوّت سرّي. اللي صوّت زي أغلب الشلة ياخد نقطة.','A question like "Who\'s most likely to be late?" appears and everyone votes secretly. Voting with the majority earns a point.'),
 start(S,su){const g={dk:shuf(range(MOST[su.lvl].length)),n:0,R:su.R};this.beg(g);return g},
 beg(g){g.q=g.dk[g.n%g.dk.length];g.ph='v';coll(g,'v'+g.n,ids())},
 done(g,c){g.tl=tally(c.got);g.top=tops(g.tl);for(const id in c.got)if(g.top.includes(c.got[id])&&id in g.sc)g.sc[id]++;g.ph='r'},
 act(g,a,pid,C,S){if(a.t==='next'&&C&&g.ph==='r'){g.n++;if(g.n>=g.R){finish(S);return}this.beg(g);return}return false},
 view(g,X){const h=head(A('سؤال ','Question ')+ofN(g.n+1,g.R))+card(A('مين فينا؟ 👉','Who\'s most likely? 👉'),B('MOST')[g.lvl][g.q],'sun');
  if(g.ph==='v')return h+cv(g,X,pid=>`<p class="hint">${A('صوتك سرّي 🤫','Your vote is secret 🤫')}</p><div class="grid2">${ids().map(id=>pbtn(id,{t:'sub',k:g.c.k,v:id,as:pid})).join('')}</div>`,{wt:A('مستنيين التصويت...','Waiting for votes...')});
  const tot=Object.values(g.tl).reduce((a,b)=>a+b,0)||1,rows=Object.entries(g.tl).sort((a,b)=>b[1]-a[1]);
  return h+`<div class="rv">${g.top.length?`<h3>${g.top.map(id=>chip(id)).join(' ')} ${g.top.length>1?A('متعادلين!','tied!'):A('خد اللقب 👑','takes the crown 👑')}</h3>`:`<h3>${A('محدش صوّت','No votes')}</h3>`}<div class="bars">${rows.map(([id,n])=>bar(chip(id),n,tot,(P(id)||{}).c)).join('')}</div><p class="note">${A('+1 لكل اللي صوّتوا للأغلبية','+1 for everyone who voted with the majority')}</p></div>`+nextBtn(g,X,g.n+1>=g.R)}
};

/* ===== Would you rather ===== */
G.wr={e:'⚖️',cat:1,min:2,lv:'N',R:10,Rmax:30,
 n:()=>A('لو خيروك','Would you rather'),Ru:()=>A('الأسئلة','questions'),
 d:()=>A('اختيارين صعبين، اختار واحد','Two tough options, pick one'),
 h:()=>A('كل سؤال فيه اختيارين صعبين، وكل واحد يختار سرّي. بعدين نشوف الشلة راحت فين، واللي مع الأغلبية ياخد نقطة.','Each question has two tough options and everyone picks secretly. Then see where the group landed; the majority earns a point.'),
 start(S,su){const g={dk:shuf(range(RATHER[su.lvl].length)),n:0,R:su.R};this.beg(g);return g},
 beg(g){g.q=g.dk[g.n%g.dk.length];g.ph='v';coll(g,'v'+g.n,ids())},
 done(g,c){g.ch=c.got;let a=0,b=0;for(const id in c.got)c.got[id]===1?b++:a++;g.ab=[a,b];g.mj=a>b?0:b>a?1:null;if(g.mj!=null)for(const id in c.got)if(c.got[id]===g.mj&&id in g.sc)g.sc[id]++;g.ph='r'},
 act(g,a,pid,C,S){if(a.t==='next'&&C&&g.ph==='r'){g.n++;if(g.n>=g.R){finish(S);return}this.beg(g);return}return false},
 view(g,X){const Q=B('RATHER')[g.lvl][g.q],or=A('ولا','or');const h=head(A('سؤال ','Question ')+ofN(g.n+1,g.R))+`<h2 class="wrq">${A('لو خيروك ⚖️','Would you rather ⚖️')}</h2>`;
  if(g.ph==='v')return h+cv(g,X,pid=>`<div class="vs">${btn(esc(Q[0]),{t:'sub',k:g.c.k,v:0,as:pid},'big2 pink')}<span class="or">${or}</span>${btn(esc(Q[1]),{t:'sub',k:g.c.k,v:1,as:pid},'big2 cyan')}</div>`,{wt:A('مستنيين الكل يختار...','Waiting for everyone...')})+(g.c&&!X.L&&!inInput(g,X)?`<div class="vs ro"><div class="vsr pink">${esc(Q[0])}</div><span class="or">${or}</span><div class="vsr cyan">${esc(Q[1])}</div></div>`:'');
  const tot=(g.ab[0]+g.ab[1])||1;
  return h+`<div class="vs ro">${[0,1].map(i=>`<div class="vsr ${i?'cyan':'pink'}${g.mj===i?' win':''}"><b class="pct">${Math.round(g.ab[i]/tot*100)}%</b><span>${esc(Q[i])}</span><div class="chips">${Object.keys(g.ch).filter(id=>g.ch[id]===i).map(id=>chip(id)).join('')}</div></div>`).join(`<span class="or">${or}</span>`)}</div><p class="note">${g.mj==null?A('متعادلين، محدش خد نقط','Tied, no points'):A('+1 للأغلبية','+1 for the majority')}</p>`+nextBtn(g,X,g.n+1>=g.R)}
};

/* ===== Funniest answer ===== */
G.qp={e:'✍️',cat:1,min:3,R:6,Rmax:20,
 n:()=>A('الإجابة الأغرب','Funniest answer'),Ru:()=>A('الأسئلة','prompts'),
 d:()=>A('اكتب أظرف إجابة والكل يصوّت','Write the funniest answer, everyone votes'),
 h:()=>A('يظهر سؤال مفتوح، وكل واحد يكتب إجابته من غير ما حد يشوف. بعدين الإجابات تظهر من غير أسامي والكل يصوّت على أحلى واحدة. كل صوت بنقطة.','An open prompt appears and everyone writes an answer in secret. Answers are shown without names and everyone votes for the best. Each vote is a point.'),
 start(S,su){const g={dk:shuf(range(QUIP.length)),n:0,R:su.R};this.beg(g);return g},
 beg(g){g.q=g.dk[g.n%g.dk.length];g.ph='w';g.ans=null;g.vc=null;coll(g,'w'+g.n,ids())},
 done(g,c){if(c.k[0]==='w'){g.ans={};for(const id in c.got){const t=clean(c.got[id],70);if(t)g.ans[id]=t}g.ao=shuf(Object.keys(g.ans));if(g.ao.length<2){g.vc={};g.ph='r';return}g.ph='v';coll(g,'v'+g.n,ids());return}
  g.vc=tally(c.got);for(const id in g.vc)if(id in g.sc)g.sc[id]+=g.vc[id];g.ph='r'},
 act(g,a,pid,C,S){if(a.t==='next'&&C&&g.ph==='r'){g.n++;if(g.n>=g.R){finish(S);return}this.beg(g);return}return false},
 view(g,X){const h=head(A('سؤال ','Prompt ')+ofN(g.n+1,g.R))+card(A('اكمل 😂','Fill it in 😂'),B('QUIP')[g.q],'sun');
  if(g.ph==='w')return h+cv(g,X,pid=>`<div class="form"><textarea id="qpa" maxlength="70" rows="2" placeholder="${A('اكتب أظرف إجابة...','Write your funniest answer...')}"></textarea></div>${ub(A('ابعت 📨','Send 📨'),'qpsub',pid,'pri')}`,{ct:A('اكتب إجابتك ومحدش يبص ✍️','Write yours, no peeking ✍️'),wt:A('مستنيين الكل يكتب...','Waiting for everyone to write...')});
  if(g.ph==='v')return h+`<p class="hint">${A('صوّت لأحلى إجابة (مش إجابتك)','Vote for the best answer (not yours)')}</p>`+cv(g,X,pid=>`<div class="opts">${g.ao.filter(a=>a!==pid).map(a=>btn(`<span>${esc(g.ans[a])}</span>`,{t:'sub',k:g.c.k,v:a,as:pid},'opt')).join('')}</div>`,{ct:A('صوّت سرّي 🤫','Vote secretly 🤫'),wt:A('مستنيين التصويت...','Waiting for votes...')});
  const rows=Object.keys(g.ans||{}).sort((a,b)=>(g.vc[b]||0)-(g.vc[a]||0));
  return h+`<div class="opts ro">${rows.length?rows.map((a,i)=>`<div class="optr${i===0&&(g.vc[a]||0)>0?' top':''}"><em>${g.vc[a]||0}</em><span>${esc(g.ans[a])}</span><div class="chips">${chip(a)}</div></div>`).join(''):`<p class="note">${A('محدش كتب حاجة 😅','Nobody wrote anything 😅')}</p>`}</div>`+nextBtn(g,X,g.n+1>=g.R)}
};

/* ===== Herd mind ===== */
G.hm={e:'🐑',cat:1,min:3,R:8,Rmax:30,
 n:()=>A('فكّر زي الشلة','Think like the group'),Ru:()=>A('الأسئلة','prompts'),
 d:()=>A('اكتب نفس إجابة الأغلبية','Match the majority\'s answer'),
 h:()=>A('يظهر طلب زي «اكتب أكلة مصرية»، وكل واحد يكتب أول حاجة في دماغه. اللي إجابته زي إجابة أغلب الشلة ياخد نقطة. اكتبوا كلمة واحدة وبنفس اللغة، والمضيف يقدر يضم الإجابات اللي معناها واحد.','A prompt like "Name an Egyptian food" appears and everyone writes the first thing that comes to mind. Matching the most common answer earns a point. Use one word in the same language; the host can merge answers that mean the same.'),
 start(S,su){const g={dk:shuf(range(HERD.ar.length)),n:0,R:su.R};this.beg(g);return g},
 beg(g){g.q=g.dk[g.n%g.dk.length];g.ph='w';g.gr=null;g.wn=[];coll(g,'w'+g.n,ids())},
 done(g,c){const m={};for(const id in c.got){const t=clean(c.got[id],30);if(!t)continue;const k=nAr(t)||t;(m[k]=m[k]||{t,ids:[]}).ids.push(id)}g.gr=Object.values(m).sort((a,b)=>b.ids.length-a.ids.length);const mx=g.gr.length?g.gr[0].ids.length:0;g.wn=mx>1?g.gr.map((x,i)=>x.ids.length===mx?i:-1).filter(i=>i>=0):[];g.ph='r'},
 act(g,a,pid,C,S){if(!C)return false;if(a.t==='hmt'&&g.ph==='r'&&g.gr[a.i]){const j=g.wn.indexOf(a.i);j<0?g.wn.push(a.i):g.wn.splice(j,1);return}
  if(a.t==='next'&&g.ph==='r'){g.wn.forEach(i=>g.gr[i].ids.forEach(id=>{if(id in g.sc)g.sc[id]++}));g.n++;if(g.n>=g.R){finish(S);return}this.beg(g);return}return false},
 view(g,X){const h=head(A('سؤال ','Prompt ')+ofN(g.n+1,g.R))+card(A('فكّر زي الشلة 🐑','Think like the group 🐑'),(EL()?HERD.en:HERD.ar)[g.q],'sun');
  if(g.ph==='w')return h+cv(g,X,pid=>`<div class="form"><input id="hma" maxlength="30" autocomplete="off" placeholder="${A('أول حاجة في دماغك...','First thing that comes to mind...')}"></div>${ub(A('ابعت 📨','Send 📨'),'hmsub',pid,'pri')}`,{ct:A('اكتب إجابتك ومحدش يبص 🐑','Write yours, no peeking 🐑'),wt:A('مستنيين الكل يكتب...','Waiting for everyone...')});
  return h+`<div class="opts ro">${g.gr.length?g.gr.map((x,i)=>{const w=g.wn.includes(i);const inner=`<em>${x.ids.length}</em><span>${esc(x.t)}</span>${w?'<b class="pt p10">+1</b>':''}<div class="chips">${x.ids.map(id=>chip(id)).join('')}</div>`;return X.C?`<button type="button" class="optr tgl${w?' top':''}" data-j="${J({t:'hmt',i})}">${inner}</button>`:`<div class="optr${w?' top':''}">${inner}</div>`}).join(''):`<p class="note">${A('محدش كتب حاجة 😅','Nobody wrote anything 😅')}</p>`}</div>${X.C?`<p class="note">${A('دوس على أي إجابة علشان تضمها للكسبانين أو تشيلها','Tap an answer to add it to (or remove it from) the winners')}</p>`:''}`+nextBtn(g,X,g.n+1>=g.R)}
};

/* ===== Spy ===== */
G.sp={e:'🕵️',cat:2,min:3,R:3,Rmax:10,
 n:()=>A('برا السالفة','The odd one out'),Ru:()=>A('الجولات','rounds'),
 d:()=>A('واحد بس مش عارف الكلمة','One person doesn\'t know the word'),
 h:()=>A('الكل بيشوف نفس الكلمة ماعدا واحد بس «برا السالفة». كل واحد يسأل التاني سؤال عن الكلمة من غير ما يفضحها، وبعدين تصوّتوا مين اللي برا. لو مسكتوه ليه فرصة يخمّن الكلمة.','Everyone sees the same word except one player, the outsider. Take turns asking each other questions about it without giving it away, then vote for the outsider. If caught, they get one chance to guess the word.'),
 start(S,su){const g={n:0,R:su.R};this.beg(g);return g},
 beg(g){g.cat=rint(SPY.length);g.w=rint(SPY[g.cat].w.length);const I=ids();g.spy=I[rint(I.length)];g.ph='s';g.te=0;g.tl=null;g.caught=0;g.gw=null;g.gok=0;coll(g,'s'+g.n,I)},
 vote(g){g.ph='v';g.te=0;coll(g,'v'+g.n,ids())},
 done(g,c){const k=c.k[0];
  if(k==='s'){g.ph='t';setT(g,150000);return}
  if(k==='v'){g.vt=c.got;g.tl=tally(c.got);const tp=tops(g.tl);g.caught=tp.length===1&&tp[0]===g.spy?1:0;
   if(g.caught){const ws=SPY[g.cat].w;g.op=shuf([g.w,...shuf(range(ws.length).filter(i=>i!==g.w)).slice(0,5)]);g.ph='sg';coll(g,'g'+g.n,[g.spy]);return}
   if(g.spy in g.sc)g.sc[g.spy]+=3;g.ph='r';return}
  g.gw=c.got[g.spy]==null?null:c.got[g.spy];g.gok=g.gw===g.w?1:0;for(const id in g.vt)if(g.vt[id]===g.spy&&id in g.sc)g.sc[id]++;if(g.gok&&g.spy in g.sc)g.sc[g.spy]+=2;g.ph='r'},
 timeout(g){if(g.ph==='t')this.vote(g)},
 act(g,a,pid,C,S){if(!C)return false;if(a.t==='tv'&&g.ph==='t'){this.vote(g);return}if(a.t==='next'&&g.ph==='r'){g.n++;if(g.n>=g.R){finish(S);return}this.beg(g);return}return false},
 role(g,pid){const C=B('SPY')[g.cat];return pid===g.spy?`<article class="qc cyan"><span class="tag">${A('دورك','Your role')}</span><p class="w">${A('انت برا السالفة 🕵️','You\'re the outsider 🕵️')}</p><small>${A('الفئة: ','Category: ')}${esc(C.n)} · ${A('حاول تفهم الكلمة من كلامهم ومتتفضحش','figure out the word from their talk and don\'t get caught')}</small></article>`:`<article class="qc cyan"><span class="tag">${A('الكلمة','The word')}</span><p class="w">${esc(C.w[g.w])}</p><small>${A('الفئة: ','Category: ')}${esc(C.n)} · ${A('واحد فيكم ميعرفهاش 👀','one of you doesn\'t know it 👀')}</small></article>`},
 view(g,X){const C=B('SPY')[g.cat];const h=head(A('جولة ','Round ')+ofN(g.n+1,g.R),`<span class="cat">${A('الفئة: ','Category: ')}${esc(C.n)}</span>`);
  if(g.ph==='s')return h+cv(g,X,pid=>this.role(g,pid)+btn(A('حفظت ✓','Got it ✓'),{t:'sub',k:g.c.k,v:1,as:pid},'pri'),{ct:A('كل واحد يشوف كلمته لوحده 🙈','Everyone sees their word alone 🙈'),wt:A('مستنيين الكل يشوف كلمته...','Waiting for everyone to see their word...')});
  if(g.ph==='t')return h+`<div class="rv"><h3>${A('اسألوا بعض 🗣️','Ask each other 🗣️')}</h3><p>${A('كل واحد يسأل اللي جنبه سؤال عن الكلمة. جاوبوا بذكاء من غير ما تفضحوا الكلمة، واللي برا السالفة يحاول ميبانش.','Take turns asking the person next to you about the word. Answer cleverly without giving it away; the outsider tries to blend in.')}</p></div>`+tmr(g)+(!X.L&&X.me?`${ui.peek?this.role(g,X.me):''}${ub(ui.peek?A('خبّي 🙈','Hide 🙈'):A('افتكر كلمتي 👁️','Show my word 👁️'),'peek','','ghost sm')}`:'')+(X.C?btn(A('يلا نصوّت 🗳️','Vote now 🗳️'),{t:'tv'},'pri'):'');
  if(g.ph==='v')return h+cv(g,X,pid=>`<p class="hint">${A('مين اللي برا السالفة؟','Who\'s the outsider?')}</p><div class="grid2">${ids().filter(i=>i!==pid).map(id=>pbtn(id,{t:'sub',k:g.c.k,v:id,as:pid})).join('')}</div>`,{ct:A('صوّت سرّي 🤫','Vote secretly 🤫'),wt:A('مستنيين التصويت...','Waiting for votes...')});
  if(g.ph==='sg')return h+`<div class="rv"><h3>${chip(g.spy)} ${A('اتمسك! 🚨','got caught! 🚨')}</h3><p>${A('بس لسه ليه فرصة يخمّن الكلمة ويكسب نقطتين','but can still guess the word for 2 points')}</p></div>`+cv(g,X,pid=>`<div class="grid2">${g.op.map(i=>btn(esc(C.w[i]),{t:'sub',k:g.c.k,v:i,as:pid},'opt c')).join('')}</div>`,{wt:esc(nm(g.spy))+A(' بيخمّن الكلمة...',' is guessing the word...'),ct:A('دي فرصتك تخمّن الكلمة 🕵️','Your chance to guess the word 🕵️')});
  const t=g.tl||{},tot=Object.values(t).reduce((a,b)=>a+b,0)||1;
  const msg=g.caught?(g.gok?`${chip(g.spy)} ${A('اتمسك بس عرف الكلمة! 😎 +2','was caught but guessed the word! 😎 +2')}`:`${A('مسكتوه!','Caught!')} ${chip(g.spy)} ${A('كان برا السالفة 🎉','was the outsider 🎉')}`):`${chip(g.spy)} ${A('كان برا السالفة وهرب منكم! 🕵️ +3','was the outsider and got away! 🕵️ +3')}`;
  return h+`<div class="rv"><h3>${msg}</h3><p>${A('الكلمة كانت: ','The word was: ')}<b class="w">${esc(C.w[g.w])}</b>${g.caught&&!g.gok&&g.gw!=null?` · ${A('هو خمّن','they guessed')} «${esc(C.w[g.gw])}»`:''}</p><div class="bars">${Object.entries(t).sort((a,b)=>b[1]-a[1]).map(([id,n])=>bar(chip(id),n,tot,(P(id)||{}).c)).join('')}</div>${g.caught?`<p class="note">${A('+1 لكل اللي صوّتوا صح','+1 for everyone who voted right')}</p>`:''}</div>`+nextBtn(g,X,g.n+1>=g.R)}
};

/* ===== Mafia ===== */
const ROLES=()=>({m:{n:A('مافيا','Mafia'),e:'😈',d:A('كل ليلة انت والمافيا تختاروا حد تخرّجوه. الصبح متتفضحش!','Each night you and the mafia pick someone to eliminate. Don\'t get exposed by day!')},d:{n:A('الدكتور','Doctor'),e:'💉',d:A('كل ليلة تختار حد تحميه، وممكن تحمي نفسك.','Each night protect someone, yourself included.')},s:{n:A('المحقق','Detective'),e:'🔎',d:A('كل ليلة تكشف حقيقة واحد: مافيا ولا لأ.','Each night find out if someone is mafia.')},c:{n:A('مواطن','Citizen'),e:'🙂',d:A('ركّز في الكلام الصبح واكتشف مين المافيا.','Listen closely by day and find the mafia.')}});
G.mf={e:'🌙',cat:2,min:5,R:1,Rmax:1,noR:1,team:1,
 n:()=>A('المافيا','Mafia'),Ru:()=>'',
 d:()=>A('أدوار سرية والموقع هو الراوي','Secret roles, the site narrates'),
 h:()=>A('كل واحد بياخد دور سرّي: مافيا، دكتور، محقق، أو مواطن. بالليل المافيا تختار ضحية، والدكتور يحمي حد، والمحقق يكشف حد. الصبح الكل يتناقش ويصوّت يخرّج مين. المواطنين يكسبوا لو خرّجوا المافيا كلها، والمافيا تكسب لو بقى عددها قد الباقيين.','Everyone gets a secret role: mafia, doctor, detective, or citizen. At night the mafia picks a victim, the doctor protects someone, the detective checks someone. By day everyone debates and votes someone out. Citizens win by removing all mafia; the mafia wins when they equal everyone else.'),
 start(S){const all=shuf(ids()),n=all.length,mc=n>=13?3:n>=8?2:1,ro={};all.forEach((id,i)=>ro[id]=i<mc?'m':i===mc?'d':i===mc+1?'s':'c');const g={ro,al:ids(),day:1,ph:'role',last:null,ex:null};coll(g,'role',ids());return g},
 night(g){g.ph='n';g.te=0;coll(g,'n'+g.day,g.al.slice())},
 dvote(g){g.ph='dv';g.te=0;coll(g,'d'+g.day,g.al.slice())},
 chk(g){const m=g.al.filter(i=>g.ro[i]==='m').length;const w=!m?'c':m>=g.al.length-m?'m':null;if(!w)return 0;g.wn=w;for(const id in g.sc)g.sc[id]=((w==='m')===(g.ro[id]==='m'))?1:0;g.ph='end';g.te=0;return 1},
 done(g,c){const k=c.k[0];
  if(k==='r'){this.night(g);return}
  if(k==='n'){const mv={};let doc=null;for(const id in c.got){const r=g.ro[id],v=c.got[id];if(r==='m'&&g.al.includes(v)&&g.ro[v]!=='m')mv[v]=(mv[v]||0)+1;if(r==='d'&&g.al.includes(v))doc=v}
   const tp=tops(mv),kill=tp.length?tp[rint(tp.length)]:null,died=kill&&kill!==doc?kill:null;if(died)g.al=g.al.filter(i=>i!==died);g.last={d:died,sv:kill&&kill===doc?1:0};g.ex=null;if(this.chk(g))return;g.ph='day';setT(g,180000);return}
  const t=tally(c.got),tp=tops(t),out=tp.length===1&&g.al.includes(tp[0])?tp[0]:null;if(out)g.al=g.al.filter(i=>i!==out);g.ex={id:out};if(this.chk(g))return;g.ph='dr'},
 timeout(g){if(g.ph==='day')this.dvote(g)},
 act(g,a,pid,C,S){if(!C)return false;if(a.t==='dv'&&g.ph==='day'){this.dvote(g);return}if(a.t==='next'&&g.ph==='dr'){g.day++;this.night(g);return}if(a.t==='fin'&&g.ph==='end'){finish(S);return}return false},
 nIn(g,pid){const RO=ROLES(),r=g.ro[pid],k=g.c.k,al=g.al,R=RO[r];const mini=`<div class="rmini">${R.e} ${A('انت','You are')} ${R.n}</div>`;
  const T=(list,lbl)=>`<p class="hint">${lbl}</p><div class="grid2">${list.map(id=>pbtn(id,{t:'sub',k,v:id,as:pid})).join('')}</div>`;
  if(r==='m'){const mates=al.filter(i=>i!==pid&&g.ro[i]==='m');return mini+(mates.length?`<p class="note">${A('شركاك:','Partners:')} ${mates.map(i=>chip(i)).join(' ')}</p>`:'')+T(al.filter(i=>g.ro[i]!=='m'),A('اختار مين تخرّجه الليلة 🔪','Pick who to eliminate tonight 🔪'))}
  if(r==='d')return mini+T(al,A('اختار مين تحميه الليلة 💉','Pick who to protect tonight 💉'));
  if(r==='s'){if(ui.det&&al.includes(ui.det)){const isM=g.ro[ui.det]==='m';return mini+`<div class="rv"><h3>${chip(ui.det)} ${isM?A('مافيا 😈','is mafia 😈'):A('مش مافيا 😇','is not mafia 😇')}</h3><p>${A('احفظها في دماغك ومتقولهاش بصراحة','Keep it to yourself')}</p></div>`+btn(A('تمام ✓','OK ✓'),{t:'sub',k,v:ui.det,as:pid},'pri')}
   return mini+`<p class="hint">${A('اختار حد تكشفه 🔎','Pick someone to check 🔎')}</p><div class="grid2">${al.filter(i=>i!==pid).map(id=>`<button type="button" class="b pl" style="--c:${P(id).c}" data-u="mfdet" data-x="${id}">${esc(nm(id))}</button>`).join('')}</div>`}
  return mini+T(al.filter(i=>i!==pid),A('انت نايم 😴 دوس على حد شاكك فيه (للتمويه بس)','You\'re asleep 😴 tap someone you suspect (just a decoy)'))},
 view(g,X){const RO=ROLES(),dead=!X.L&&X.me&&!g.al.includes(X.me)&&g.ph!=='end';const R=id=>RO[g.ro[id]]||RO.c;
  const h=head(g.ph==='role'?A('توزيع الأدوار','Dealing roles'):(g.ph==='n'?A('الليلة ','Night '):A('اليوم ','Day '))+g.day,`<span class="cat">${A('في اللعبة: ','Alive: ')}${g.al.length}</span>`)+(dead?`<div class="dead">${A('انت خرجت من اللعبة 💀 اتفرج بس ومتقولش حاجة','You\'re out 💀 watch quietly')}</div>`:'');
  const roleCard=pid=>{const r=R(pid),mates=g.ro[pid]==='m'?ids().filter(i=>i!==pid&&g.ro[i]==='m'):[];return `<article class="qc vio"><span class="tag">${A('دورك السري','Your secret role')}</span><p class="w">${r.e} ${r.n}</p><small>${r.d}</small>${mates.length?`<small>${A('شركاك في المافيا: ','Your mafia partners: ')}${mates.map(i=>esc(nm(i))).join(', ')}</small>`:''}</article>`};
  if(g.ph==='role')return h+cv(g,X,pid=>roleCard(pid)+btn(A('حفظت دوري ✓','Got my role ✓'),{t:'sub',k:'role',v:1,as:pid},'pri'),{ct:A('كل واحد يشوف دوره لوحده 🤫','Everyone sees their role alone 🤫'),wt:A('مستنيين الكل يشوف دوره...','Waiting for everyone to see their role...')});
  if(g.ph==='n')return h+`<div class="night">🌙 ${A('الدنيا ليل... الكل يغمّض','Night falls... everyone close your eyes')}</div>`+cv(g,X,pid=>this.nIn(g,pid),{ct:A('دورك بالليل، محدش يبص 🌙','Your night turn, no peeking 🌙'),wt:A('الليل شغال... 🌙','The night is busy... 🌙')});
  if(g.ph==='day'){const L=g.last||{};return h+`<div class="rv"><h3>☀️ ${A('صباح الخير!','Good morning!')}</h3><p>${L.d?`${A('للأسف','Sadly')} ${chip(L.d)} ${A('خرج الليلة دي 💀','was eliminated tonight 💀')}`:(L.sv?A('المافيا حاولت تخرّج حد، بس الدكتور أنقذه 💉','The mafia struck, but the doctor saved them 💉'):A('الليلة عدّت بسلام، محدش خرج 😌','A quiet night, nobody was eliminated 😌'))}</p></div><p class="hint">${A('اتناقشوا: مين شكله مافيا؟','Discuss: who looks like mafia?')}</p><div class="chips">${g.al.map(id=>chip(id)).join('')}</div>`+tmr(g)+(X.C?btn(A('يلا نصوّت 🗳️','Vote now 🗳️'),{t:'dv'},'pri'):'')}
  if(g.ph==='dv')return h+cv(g,X,pid=>`<p class="hint">${A('تخرّجوا مين؟','Who do you vote out?')}</p><div class="grid2">${g.al.filter(i=>i!==pid).map(id=>pbtn(id,{t:'sub',k:g.c.k,v:id,as:pid})).join('')}${btn(A('نعدّيها 🤷','Skip 🤷'),{t:'sub',k:g.c.k,v:'-',as:pid},'ghost')}</div>`,{ct:A('صوّت سرّي 🗳️','Vote secretly 🗳️'),wt:A('مستنيين التصويت...','Waiting for votes...')});
  if(g.ph==='dr'){const e=g.ex||{};return h+`<div class="rv">${e.id?`<h3>${chip(e.id)} ${A('خرج بالتصويت','was voted out')}</h3><p>${A('وكان ','They were ')}${R(e.id).e} ${R(e.id).n}</p>`:`<h3>${A('متفقتوش، محدش خرج 🤷','No agreement, nobody leaves 🤷')}</h3>`}</div>`+(X.C?btn(A('الليل جه 🌙','Night falls 🌙'),{t:'next'},'pri'):wait(A('المضيف هيكمّل...','The host will continue...')))}
  return h+`<div class="rv"><h3>${g.wn==='m'?A('المافيا كسبت 😈','The mafia wins 😈'):A('المواطنين كسبوا 🎉','The citizens win 🎉')}</h3><div class="roles">${ids().map(id=>`<div class="rr">${chip(id)}<span>${R(id).e} ${R(id).n}</span>${g.al.includes(id)?'':'<i>💀</i>'}</div>`).join('')}</div></div>`+(X.C?btn(A('النتيجة 🏁','Results 🏁'),{t:'fin'},'pri'):wait(A('المضيف هيكمّل...','The host will continue...')))}
};

/* ===== One night: werewolf ===== */
const WROLES=()=>({w:{n:A('ديب','Werewolf'),e:'🐺',d:A('انت والديابة لازم محدش فيكم يتمسك الصبح.','You and the wolves must not get caught by morning.')},s:{n:A('العرّافة','Seer'),e:'🔮',d:A('تقدر تشوف دور حد واحد بالليل.','You can see one player\'s role at night.')},r:{n:A('الحرامي','Robber'),e:'🦹',d:A('تبدّل دورك بدور حد، وتشوف دورك الجديد.','Swap your role with someone and see your new role.')},t:{n:A('المشاغب','Troublemaker'),e:'🃏',d:A('تبدّل دور اتنين غيرك من غير ما تشوفهم.','Swap two other players\' roles without looking.')},v:{n:A('قروي','Villager'),e:'🧑‍🌾',d:A('ملكش قدرة، بس عقلك هو سلاحك الصبح.','No power, just your wits in the morning.')}});
G.ww={e:'🐺',cat:2,min:4,R:1,Rmax:1,noR:1,team:1,
 n:()=>A('ليلة الديب','One night werewolf'),Ru:()=>'',
 d:()=>A('ليلة واحدة، تصويت واحد','One night, one vote'),
 h:()=>A('كل واحد بياخد دور سرّي: ديب، عرّافة، حرامي، مشاغب، أو قروي. في ليلة واحدة العرّافة تشوف دور حد، والحرامي يبدّل دوره مع حد، والمشاغب يبدّل دور اتنين. الصبح تتناقشوا وتصوّتوا مرة واحدة: لو خرّجتوا ديب، القرية تكسب. خلي بالك، دورك ممكن يكون اتغيّر وانت نايم!','Everyone gets a secret role: werewolf, seer, robber, troublemaker, or villager. In one night the seer peeks at a role, the robber swaps roles with someone, and the troublemaker swaps two others. In the morning you debate and vote once: eliminate a werewolf and the village wins. Careful, your role may have changed while you slept!'),
 start(S){const all=shuf(ids()),n=all.length,wc=n>=12?3:n>=7?2:1,ro={};let i=0;all.forEach(id=>{ro[id]=i<wc?'w':i===wc?'s':i===wc+1&&n>=5?'r':i===wc+2&&n>=6?'t':'v';i++});const g={ro0:ro,ro:null,ph:'n',acts:null};coll(g,'n',ids());return g},
 done(g,c){if(c.k==='n'){const ro=Object.assign({},g.ro0);const by=r=>Object.keys(ro).find(i=>g.ro0[i]===r);const rb=by('r'),tm=by('t');const sw=(a,b)=>{if(a in ro&&b in ro&&a!==b){const x=ro[a];ro[a]=ro[b];ro[b]=x}};
   if(rb&&typeof c.got[rb]==='string')sw(rb,c.got[rb]);if(tm&&Array.isArray(c.got[tm])&&c.got[tm].length===2)sw(c.got[tm][0],c.got[tm][1]);g.ro=ro;g.ph='day';setT(g,180000);return}
  const t=tally(c.got),vals=Object.values(t),mx=vals.length?Math.max(...vals):0;g.dead=mx>1?Object.keys(t).filter(k=>t[k]===mx):[];g.tl=t;
  const wolf=g.dead.some(id=>g.ro[id]==='w');g.wn=wolf?'v':'w';for(const id in g.sc)g.sc[id]=((g.wn==='w')===(g.ro[id]==='w'))?1:0;g.ph='end';g.te=0},
 timeout(g){if(g.ph==='day')this.vote(g)},
 vote(g){g.ph='v';g.te=0;coll(g,'v',ids())},
 act(g,a,pid,C,S){if(!C)return false;if(a.t==='wv'&&g.ph==='day'){this.vote(g);return}if(a.t==='fin'&&g.ph==='end'){finish(S);return}return false},
 nIn(g,pid){const RO=WROLES(),r=g.ro0[pid],R=RO[r],k=g.c.k;const mini=`<article class="qc vio"><span class="tag">${A('دورك','Your role')}</span><p class="w">${R.e} ${R.n}</p><small>${R.d}</small></article>`;const others=ids().filter(i=>i!==pid);
  if(r==='w'){const m=others.filter(i=>g.ro0[i]==='w');return mini+`<p class="hint">${m.length?A('الديابة اللي معاك: ','Your fellow wolves: ')+m.map(i=>chip(i)).join(' '):A('انت الديب الوحيد 🐺','You\'re the only wolf 🐺')}</p>`+btn(A('تمام ✓','OK ✓'),{t:'sub',k,v:1,as:pid},'pri')}
  if(r==='s'||r==='r'){if(ui.det&&others.includes(ui.det)){const x=RO[g.ro0[ui.det]];return mini+`<div class="rv"><h3>${r==='s'?chip(ui.det)+' '+A('دوره','is')+' '+x.e+' '+x.n:A('دورك الجديد: ','Your new role: ')+x.e+' '+x.n}</h3>${r==='r'?`<p>${A('واتبدّلت مع','Swapped with')} ${chip(ui.det)}</p>`:''}</div>`+btn(A('تمام ✓','OK ✓'),{t:'sub',k,v:ui.det,as:pid},'pri')}
   return mini+`<p class="hint">${r==='s'?A('اختار حد تشوف دوره 🔮','Pick someone to peek at 🔮'):A('اختار حد تسرق دوره 🦹','Pick someone to rob 🦹')}</p><div class="grid2">${others.map(id=>`<button type="button" class="b pl" style="--c:${P(id).c}" data-u="mfdet" data-x="${id}">${esc(nm(id))}</button>`).join('')}</div>`}
  if(r==='t'){const s=ui.sel||(ui.sel=[]);return mini+`<p class="hint">${A('اختار اتنين تبدّلهم 🃏','Pick two players to swap 🃏')}</p><div class="chips pick">${others.map(id=>`<button type="button" class="pc tg${s.includes(id)?' on':''}" style="--c:${P(id).c}" data-u="sel2" data-x="${id}">${esc(nm(id))}</button>`).join('')}</div>`+(s.length===2?btn(A('بدّلهم 🃏','Swap them 🃏'),{t:'sub',k,v:s.slice(),as:pid},'pri'):'')+btn(A('مش عايز أبدّل','Don\'t swap'),{t:'sub',k,v:0,as:pid},'ghost sm')}
  return mini+`<p class="hint">${A('دوس على حد شاكك فيه (للتمويه بس)','Tap someone you suspect (just a decoy)')}</p><div class="grid2">${others.map(id=>pbtn(id,{t:'sub',k,v:id,as:pid})).join('')}</div>`},
 view(g,X){const RO=WROLES();const h=head(g.ph==='n'?A('الليلة 🌙','The night 🌙'):A('الصبح ☀️','Morning ☀️'));
  if(g.ph==='n')return h+cv(g,X,pid=>this.nIn(g,pid),{ct:A('دورك بالليل، محدش يبص 🌙','Your night turn, no peeking 🌙'),wt:A('القرية نايمة... 🌙','The village sleeps... 🌙')});
  if(g.ph==='day')return h+`<div class="rv"><h3>${A('اتناقشوا! مين الديب؟ 🐺','Debate! Who\'s the werewolf? 🐺')}</h3><p>${A('كل واحد يقول دوره (صح أو كدب). افتكروا إن الأدوار ممكن تكون اتبدّلت بالليل.','Everyone claims a role (true or not). Remember roles may have been swapped in the night.')}</p></div>`+tmr(g)+(X.C?btn(A('يلا نصوّت 🗳️','Vote now 🗳️'),{t:'wv'},'pri'):'');
  if(g.ph==='v')return h+cv(g,X,pid=>`<p class="hint">${A('صوّت على الديب','Vote for the werewolf')}</p><div class="grid2">${ids().filter(i=>i!==pid).map(id=>pbtn(id,{t:'sub',k:g.c.k,v:id,as:pid})).join('')}</div>`,{ct:A('صوّت سرّي 🗳️','Vote secretly 🗳️'),wt:A('مستنيين التصويت...','Waiting for votes...')});
  return h+`<div class="rv"><h3>${g.wn==='v'?A('القرية كسبت 🎉','The village wins 🎉'):A('الديابة كسبت 🐺','The werewolves win 🐺')}</h3><p>${g.dead.length?A('خرج: ','Eliminated: ')+g.dead.map(i=>chip(i)).join(' '):A('محدش خرج','Nobody was eliminated')}</p><div class="roles">${ids().map(id=>{const a=RO[g.ro0[id]],b=RO[g.ro[id]];return `<div class="rr">${chip(id)}<span>${a.e} ${a.n}${g.ro0[id]!==g.ro[id]?` → ${b.e} ${b.n}`:''}</span>${g.dead.includes(id)?'<i>💀</i>':''}</div>`}).join('')}</div></div>`+(X.C?btn(A('النتيجة 🏁','Results 🏁'),{t:'fin'},'pri'):wait(A('المضيف هيكمّل...','The host will continue...')))}
};

/* ===== Know me ===== */
G.km={e:'🫶',cat:2,min:2,R:2,Rmax:5,
 n:()=>A('انت عارفني قد إيه؟','How well do you know me?'),Ru:()=>A('الأسئلة لكل واحد','questions each'),
 d:()=>A('خمّن صاحبك هيختار إيه','Guess what your friend picks'),
 h:()=>A('كل دور يظهر سؤال عن واحد فيكم، وهو يختار إجابته بصراحة من غير ما حد يشوف. الباقيين يخمّنوا هو اختار إيه. كل تخمين صح بنقطة للي خمّن ونقطة للي اتسأل.','Each turn a question about one player appears; they answer honestly in secret. Everyone else guesses their pick. Each right guess is a point for the guesser and for the player.'),
 start(S,su){const g={ord:order(),t:0,n:0,tot:ids().length*su.R,dk:shuf(range(KNOW.length))};this.beg(g);return g},
 beg(g){g.q=g.dk[g.n%g.dk.length];g.ph='a';g.ans=null;g.gs=null;coll(g,'a'+g.n,[curOf(g)])},
 adv(g,S){g.n++;g.t++;if(g.n>=g.tot){finish(S);return}this.beg(g)},
 done(g,c,S){const cur=curOf(g);if(c.k[0]==='a'){if(!(cur in c.got)){this.adv(g,S);return}g.ans=c.got[cur];g.ph='g';coll(g,'g'+g.n,g.ord.filter(i=>i!==cur));return}
  g.gs=c.got;let ok=0;for(const id in c.got)if(c.got[id]===g.ans&&id in g.sc){g.sc[id]++;ok++}g.sc[cur]+=ok;g.ph='r'},
 act(g,a,pid,C,S){if(a.t==='next'&&C&&g.ph==='r'){this.adv(g,S);return}return false},
 view(g,X){const cur=curOf(g),K=B('KNOW')[g.q],op=K.slice(1);const h=turnHead(g,cur,A('سؤال','Question'))+card(A('سؤال عن ','About ')+esc(nm(cur)),K[0],'cyan');
  const O=pid=>`<div class="opts">${op.map((o,i)=>btn(`<em>${ABCD(i)}</em><span>${esc(o)}</span>`,{t:'sub',k:g.c.k,v:i,as:pid},'opt')).join('')}</div>`;
  if(g.ph==='a')return h+cv(g,X,pid=>`<p class="hint">${A('جاوب بصراحة يا','Answer honestly,')} ${esc(nm(cur))}</p>`+O(pid),{ct:A('اختار إجابتك ومحدش يشوف 🤫','Pick your answer, no peeking 🤫'),wt:esc(nm(cur))+A(' بيختار إجابته...',' is answering...')});
  if(g.ph==='g')return h+cv(g,X,pid=>`<p class="hint">${esc(nm(cur))} ${A('اختار إيه؟','picked what?')}</p>`+O(pid),{ct:A('خمّن من غير ما حد يشوف 🤔','Guess secretly 🤔'),wt:A('مستنيين التخمينات...','Waiting for guesses...')});
  return h+`<div class="opts ro">${op.map((o,i)=>`<div class="optr${i===g.ans?' top':''}"><em>${i===g.ans?'✓':ABCD(i)}</em><span>${esc(o)}</span><div class="chips">${Object.keys(g.gs||{}).filter(id=>g.gs[id]===i).map(id=>chip(id)).join('')}</div></div>`).join('')}</div>`+nextBtn(g,X,g.n+1>=g.tot)}
};

/* ===== Letters ===== */
const LTCN=()=>EL()?['Name','Animal','Plant','Thing','Country']:['اسم','حيوان','نبات','جماد','بلاد'];
const LETTERS={ar:'أبتجحخدرزسشصطعغفقكلمنهوي'.split(''),en:'ABCDEFGHIJKLMNOPRSTW'.split('')};
G.lt={e:'🔤',cat:3,min:2,R:5,Rmax:15,
 n:()=>A('اسم حيوان نبات','Name, animal, plant'),Ru:()=>A('الحروف','letters'),
 d:()=>A('5 كلمات بنفس الحرف','5 words, one letter'),
 h:()=>A('يطلع حرف عشوائي، وكل واحد يكتب اسم وحيوان ونبات وجماد وبلد بيبدأوا بالحرف ده. الإجابة اللي محدش كتبها غيرك بـ 10، والمكررة بـ 5. المضيف يقدر يلغي أي إجابة غلط. الحرف بيبقى بلغة المضيف.','A random letter appears and everyone writes a name, animal, plant, thing, and country starting with it. Unique answers score 10, shared ones 5. The host can reject wrong answers. The letter follows the host\'s language.'),
 start(S,su){const la=App.lang;const g={la,dk:shuf(range(LETTERS[la].length)),n:0,R:su.R};this.beg(g);return g},
 beg(g){g.L=g.dk[g.n%g.dk.length];g.ph='w';g.ans=null;g.tg=[];coll(g,'w'+g.n,ids());if(App.mode==='room')setT(g,90000);else g.te=0},
 done(g,c){g.ans={};for(const id in c.got){const v=c.got[id];g.ans[id]=range(5).map(i=>Array.isArray(v)?clean(v[i],16):'')}g.ph='r';g.te=0},
 timeout(g){if(g.ph==='w'&&g.c)skipSoon(g)},
 ok(g,id,i){const v=g.ans[id][i];if(!v)return false;let a=nAr(v).startsWith(nAr(LETTERS[g.la][g.L]));if(g.tg.includes(id+':'+i))a=!a;return a},
 score(g){const r={};for(const id in g.ans)r[id]=[0,0,0,0,0];for(let i=0;i<5;i++){const cnt={};for(const id in g.ans)if(this.ok(g,id,i)){const k=nAr(g.ans[id][i]);cnt[k]=(cnt[k]||0)+1}for(const id in g.ans)if(this.ok(g,id,i))r[id][i]=cnt[nAr(g.ans[id][i])]>1?5:10}return r},
 act(g,a,pid,C,S){if(!C)return false;
  if(a.t==='ltt'&&g.ph==='r'&&typeof a.k==='string'){const i=g.tg.indexOf(a.k);i<0?g.tg.push(a.k):g.tg.splice(i,1);return}
  if(a.t==='ltok'&&g.ph==='r'){const sc=this.score(g);for(const id in sc)if(id in g.sc)g.sc[id]+=sc[id].reduce((x,y)=>x+y,0);g.n++;if(g.n>=g.R){finish(S);return}this.beg(g);return}
  return false},
 view(g,X){const Lt=LETTERS[g.la][g.L],C=LTCN();const h=head(A('حرف ','Letter ')+ofN(g.n+1,g.R))+`<div class="letter">${Lt}</div>`;
  if(g.ph==='w')return h+tmr(g)+cv(g,X,pid=>`<div class="form">${C.map((c,i)=>`<label class="fl2"><span>${c}</span><input id="lt${i}" maxlength="16" autocomplete="off" placeholder="${Lt}..."></label>`).join('')}</div>${ub(A('خلّصت ✋','Done ✋'),'ltsub',pid,'pri')}`,{ct:A('اكتب إجاباتك ومحدش يبص 👀','Write yours, no peeking 👀'),wt:A('مستنيين الكل يخلّص...','Waiting for everyone to finish...')});
  const sc=this.score(g),pl=Object.keys(g.ans);
  return h+`<div class="lrev">${C.map((c,i)=>`<div class="lcat"><h4>${c}</h4>${pl.map(id=>{const v=g.ans[id][i],p=sc[id][i];const inner=`${chip(id)}<span class="av">${v?esc(v):'—'}</span><b class="pt p${p}">${p?'+'+p:'✗'}</b>`;return X.C&&v?`<button type="button" class="lr" data-j="${J({t:'ltt',k:id+':'+i})}">${inner}</button>`:`<div class="lr">${inner}</div>`}).join('')}</div>`).join('')}</div><div class="chips tot">${pl.map(id=>chip(id,' +'+sc[id].reduce((x,y)=>x+y,0))).join('')}</div>`+(X.C?`<p class="note">${A('دوس على أي إجابة علشان تلغيها أو ترجّعها','Tap an answer to reject or restore it')}</p>`+btn(g.n+1>=g.R?A('اعتمد النقط والنتيجة 🏁','Confirm & see results 🏁'):A('اعتمد النقط ✅','Confirm points ✅'),{t:'ltok'},'pri'):wait(A('المضيف بيراجع الإجابات...','The host is reviewing...')))}
};

/* ===== Proverbs ===== */
G.pv={e:'📜',cat:3,min:2,R:10,Rmax:40,
 n:()=>A('كمّل المثل','Finish the proverb'),Ru:()=>A('الأمثال','proverbs'),
 d:()=>A('أسرع واحد يكمّل صح','Fastest right answer wins'),
 h:()=>A('يظهر أول المثل و4 اختيارات لآخره. كل إجابة صح بنقطة، وفي الأوضة أول واحد يجاوب صح ياخد نقطتين. الأمثال بتبقى بلغة المضيف.','The start of a proverb appears with 4 endings. Every right answer is a point; in a room, the first correct answer gets 2. Proverbs follow the host\'s language.'),
 start(S,su){const la=App.lang;const g={la,dk:shuf(range(PROV[la].length)),n:0,R:su.R};this.beg(g);return g},
 beg(g){g.q=g.dk[g.n%g.dk.length];g.op=shuf([0,1,2,3]);g.ph='q';g.gs=null;g.fst=null;coll(g,'q'+g.n,ids());if(App.mode==='room')setT(g,15000);else g.te=0},
 done(g,c){g.gs=c.got;const ks=Object.keys(c.got);g.fst=App.mode==='room'?(ks.find(id=>c.got[id]===0)||null):null;for(const id of ks)if(c.got[id]===0&&id in g.sc)g.sc[id]+=id===g.fst?2:1;g.ph='r';g.te=0},
 timeout(g){if(g.ph==='q'&&g.c)skipSoon(g)},
 act(g,a,pid,C,S){if(a.t==='next'&&C&&g.ph==='r'){g.n++;if(g.n>=g.R){finish(S);return}this.beg(g);return}return false},
 view(g,X){const Q=PROV[g.la][g.q];const h=head(A('مثل ','Proverb ')+ofN(g.n+1,g.R))+card(A('كمّل 📜','Finish it 📜'),Q[0]+' ...','orng');
  if(g.ph==='q')return h+tmr(g)+cv(g,X,pid=>`<div class="opts">${g.op.map((o,i)=>btn(`<em>${ABCD(i)}</em><span>${esc(Q[1+o])}</span>`,{t:'sub',k:g.c.k,v:o,as:pid},'opt')).join('')}</div>`,{ct:A('جاوب من غير ما حد يشوف 🤫','Answer secretly 🤫'),wt:A('مستنيين الإجابات...','Waiting for answers...')});
  return h+`<div class="opts ro">${g.op.map((o,i)=>`<div class="optr${o===0?' top':''}"><em>${o===0?'✓':ABCD(i)}</em><span>${esc(Q[1+o])}</span><div class="chips">${Object.keys(g.gs||{}).filter(id=>g.gs[id]===o).map(id=>chip(id,id===g.fst?' ⚡':'')).join('')}</div></div>`).join('')}</div>${g.fst?`<p class="note">⚡ ${A('أسرع واحد خد نقطتين','Fastest correct got 2 points')}</p>`:''}`+nextBtn(g,X,g.n+1>=g.R)}
};

/* ===== Estimation ===== */
G.es={e:'🎯',cat:3,min:2,R:8,Rmax:40,
 n:()=>A('الأقرب يكسب','Closest wins'),Ru:()=>A('الأسئلة','questions'),
 d:()=>A('خمّن الرقم، الأقرب ياخد النقط','Guess the number, closest scores'),
 h:()=>A('سؤال إجابته رقم، وكل واحد يكتب تخمينه سرّي. الأقرب للإجابة الصح ياخد نقطتين، واللي بعده نقطة.','A question with a number answer; everyone guesses secretly. Closest gets 2 points, second closest gets 1.'),
 start(S,su){const g={dk:shuf(range(EST.ar.length)),n:0,R:su.R};this.beg(g);return g},
 beg(g){g.q=g.dk[g.n%g.dk.length];g.ph='q';g.gs=null;coll(g,'q'+g.n,ids())},
 done(g,c){const ans=+EST.ar[g.q][1];const L=[];for(const id in c.got){const v=+c.got[id];if(isFinite(v))L.push([id,v,Math.abs(v-ans)])}L.sort((a,b)=>a[2]-b[2]);g.gs=L;
  const d=[...new Set(L.map(x=>x[2]))];L.forEach(x=>{const r=d.indexOf(x[2]);if(r===0&&x[0] in g.sc)g.sc[x[0]]+=2;else if(r===1&&x[0] in g.sc)g.sc[x[0]]+=1});g.ph='r'},
 act(g,a,pid,C,S){if(a.t==='next'&&C&&g.ph==='r'){g.n++;if(g.n>=g.R){finish(S);return}this.beg(g);return}return false},
 view(g,X){const Q=(EL()?EST.en:EST.ar)[g.q];const h=head(A('سؤال ','Question ')+ofN(g.n+1,g.R))+card(A('خمّن 🎯','Guess 🎯'),Q[0],'orng');const fmt=v=>Number(v).toLocaleString(EL()?'en-US':'ar-EG');
  if(g.ph==='q')return h+cv(g,X,pid=>`<div class="form"><input id="esa" inputmode="decimal" autocomplete="off" dir="ltr" placeholder="${A('اكتب رقم','Type a number')}"></div>${ub(A('ابعت 📨','Send 📨'),'essub',pid,'pri')}`,{ct:A('اكتب تخمينك ومحدش يبص 🎯','Write your guess, no peeking 🎯'),wt:A('مستنيين التخمينات...','Waiting for guesses...')});
  const d=[...new Set((g.gs||[]).map(x=>x[2]))];
  return h+`<div class="rv"><h3>${A('الإجابة: ','Answer: ')}<b class="w">${fmt(Q[1])}</b></h3></div><ol class="rk">${(g.gs||[]).map(([id,v,df])=>{const r=d.indexOf(df);return `<li class="${r===0?'w':''}"><span class="pos">${r===0?'🎯':r===1?'👌':''}</span>${chip(id)}<b>${fmt(v)}</b><em>${r===0?'+2':r===1?'+1':''}</em></li>`}).join('')}</ol>`+nextBtn(g,X,g.n+1>=g.R)}
};

/* ===== Draw ===== */
G.dr={e:'🎨',cat:3,min:3,lv:'D',R:1,Rmax:4,
 n:()=>A('ارسم وخمّن','Draw & guess'),Ru:()=>A('اللفّات','rounds'),
 d:()=>A('ارسم والباقيين يخمّنوا','Draw it, they guess'),
 h:()=>A('اللي عليه الدور يشوف كلمة ويرسمها على الموبايل في دقيقة ونص، والباقيين يخمّنوا بصوت عالي. أول واحد يعرف ياخد نقطة، والرسّام ياخد نقطة كمان.','The player whose turn it is sees a word and draws it on the phone within 90 seconds while everyone shouts guesses. The first to get it scores, and so does the artist.'),
 start(S,su){const g={ord:order(),t:0,n:0,tot:ids().length*su.R,dk:shuf(range(DRAW[su.lvl].length))};this.beg(g);return g},
 beg(g){g.w=g.dk[g.n%g.dk.length];g.ph='rd';g.te=0;g.lw=null},
 act(g,a,pid,C,S){const cur=curOf(g);if(!(C||pid===cur))return false;
  if(a.t==='go'&&g.ph==='rd'){g.ph='d';goT(g,90000);return}
  if(a.t==='got'&&g.ph==='d'){g.lw=a.w&&a.w!==cur&&(a.w in g.sc)?a.w:null;if(g.lw){g.sc[g.lw]++;g.sc[cur]++}g.ph='r';g.te=0;return}
  if(a.t==='next'&&g.ph==='r'){g.n++;g.t++;if(g.n>=g.tot){finish(S);return}this.beg(g);return}
  return false},
 view(g,X){const cur=curOf(g),me=X.L||X.me===cur,word=B('DRAW')[g.lvl][g.w],h=turnHead(g,cur,A('رسمة','Drawing'));
  if(g.ph==='rd'){if(me)return h+`<div class="curt"><div class="big">🎨</div><h2>${X.L?A('الموبايل مع ','Phone goes to ')+chip(cur):A('دورك ترسم!','Your turn to draw!')}</h2><p>${A('الباقيين ميبصّوش على الشاشة 🙈','No peeking at the screen 🙈')}</p>${btn(A('وريني الكلمة وابدأ ⏱️','Show the word & start ⏱️'),{t:'go'},'pri xl')}</div>`;return h+wait(esc(nm(cur))+A(' بيجهّز الرسمة...',' is getting ready...'))+(X.C?btn(A('ابدأ بداله','Start for them'),{t:'go'},'ghost sm'):'')}
  const guess=`<p class="hint">${A('مين عرف الأول؟','Who got it first?')}</p><div class="chips pick">${ids().filter(i=>i!==cur).map(id=>`<button type="button" class="pc tg" style="--c:${P(id).c}" data-j="${J({t:'got',w:id})}">${esc(nm(id))}</button>`).join('')}</div>${btn(A('محدش عرف 😅','Nobody got it 😅'),{t:'got',w:null},'ghost sm')}`;
  if(g.ph==='d'){if(me)return h+cdown(g)+`<div class="word"><small>${A('ارسم:','Draw:')}</small><b>${esc(word)}</b></div>`+tmr(g)+`<div class="pad"><canvas id="cv"></canvas><div class="tools">${['#1b1433','#ff4f9a','#2b8cff','#19b37a','#ff8a3d'].map(c=>`<button type="button" class="sw${c===App.pen?' on':''}" style="--c:${c}" data-u="pen" data-x="${c}" aria-label="${A('لون','Color')}"></button>`).join('')}<button type="button" class="sw er${App.pen==='er'?' on':''}" data-u="pen" data-x="er" aria-label="${A('أستيكة','Eraser')}">🧽</button><button type="button" class="sw" data-u="clr" aria-label="${A('امسح الرسمة','Clear')}">🗑️</button></div></div>`+guess;
   return h+cdown(g)+`<div class="rv"><h3>${chip(cur)} ${A('بيرسم ✏️','is drawing ✏️')}</h3><p>${A('بصّوا على موبايله وقولوا الإجابة بصوت عالي!','Look at their phone and shout your guesses!')}</p></div>`+tmr(g)+(X.C?guess:'')}
  return h+`<div class="rv"><h3>${A('الكلمة كانت: ','The word was: ')}<b class="w">${esc(word)}</b></h3><p>${g.lw?`${chip(g.lw)} ${A('عرفها! +1 ليه و +1 لـ','got it! +1 to them and +1 to')} ${chip(cur)}`:A('محدش عرف 😅','Nobody got it 😅')}</p></div>`+(X.C||me?btn(g.n+1>=g.tot?A('النتيجة 🏁','Results 🏁'):A('اللي بعده ⬅','Next ➡'),{t:'next'},'pri'):wait(A('المضيف هيكمّل...','The host will continue...')))}
};

/* ===== Taboo ===== */
G.tb={e:'🚫',cat:3,min:2,lv:'D',R:1,Rmax:4,
 n:()=>A('الكلمة الممنوعة','Taboo'),Ru:()=>A('اللفّات','rounds'),
 d:()=>A('اشرح من غير الكلمات الممنوعة','Explain without the banned words'),
 h:()=>A('اللي عليه الدور معاه دقيقة يشرح أكبر عدد كلمات للباقيين، من غير ما يقول الكلمة نفسها أو الكلمات الممنوعة اللي تحتها. كل كلمة صح بنقطة، وكل غلطة بتخصم نقطة. في الفرق، اللي بيخمّنوا هما فريقه.','You have one minute to get the others to guess as many words as possible without saying the word or the banned words under it. Each correct word is a point, each slip loses one. In teams, your teammates guess.'),
 start(S,su){const g={ord:order(),t:0,n:0,tot:ids().length*su.R,dk:shuf(range(TABOO[su.lvl].length)),p:0};this.beg(g);return g},
 beg(g){g.ph='rd';g.te=0;g.rs=0;g.cnt=[0,0,0]},
 nw(g){g.w=g.dk[g.p++%g.dk.length]},
 timeout(g){if(g.ph==='p'){g.ph='s';g.sc[curOf(g)]+=g.rs}},
 act(g,a,pid,C,S){const cur=curOf(g);if(!(C||pid===cur))return false;
  if(a.t==='go'&&g.ph==='rd'){g.ph='p';this.nw(g);goT(g,60000);return}
  if(a.t==='tbm'&&g.ph==='p'&&[0,1,2].includes(a.v)&&a.w===g.w){g.cnt[a.v]++;g.rs+=[1,0,-1][a.v];this.nw(g);return}
  if(a.t==='next'&&g.ph==='s'){g.n++;g.t++;if(g.n>=g.tot){finish(S);return}this.beg(g);return}
  return false},
 view(g,X){const cur=curOf(g),me=X.L||X.me===cur,h=turnHead(g,cur);
  if(g.ph==='rd'){if(me)return h+`<div class="curt"><div class="big">🗣️</div><h2>${X.L?A('الموبايل مع ','Phone goes to ')+chip(cur):A('دورك تشرح!','Your turn to explain!')}</h2><p>${A('معاك دقيقة. اللي بيخمّنوا ميبصّوش على الشاشة.','You have a minute. Guessers, don\'t look at the screen.')}</p>${btn(A('ابدأ الدقيقة ⏱️','Start the minute ⏱️'),{t:'go'},'pri xl')}</div>`;return h+wait(esc(nm(cur))+A(' بيجهّز...',' is getting ready...'))}
  if(g.ph==='p'){if(me){const T=B('TABOO')[g.lvl][g.w];return h+cdown(g)+tmr(g)+`<article class="qc orng tab"><span class="tag">${A('اشرح','Explain')}</span><p class="w">${esc(T[0])}</p><small>${A('ممنوع تقول:','Don\'t say:')}</small><div class="ban">${T.slice(1).map(x=>`<span>${esc(x)}</span>`).join('')}</div></article><div class="tri">${btn(A('صح ✅','Got it ✅'),{t:'tbm',v:0,w:g.w},'ok')}${btn(A('باص ⏭','Pass ⏭'),{t:'tbm',v:1,w:g.w},'ghost')}${btn(A('قال ممنوع 🚫','Said a taboo 🚫'),{t:'tbm',v:2,w:g.w},'bad')}</div><p class="score">${A('النقط دلوقتي: ','Points so far: ')}<b>${g.rs}</b></p>`}
   return h+cdown(g)+`<div class="rv"><h3>${chip(cur)} ${A('بيشرح 🗣️','is explaining 🗣️')}</h3><p>${A('خمّنوا بصوت عالي!','Shout your guesses!')}</p></div>`+tmr(g)+`<p class="score">${A('جاب لحد دلوقتي: ','So far: ')}<b>${g.rs}</b></p>`}
  return h+`<div class="rv"><h3>${A('الوقت خلص! ⏰','Time\'s up! ⏰')}</h3><p>${chip(cur)} ${A('جاب','scored')} <b>${g.rs}</b></p><p class="note">${g.cnt[0]} ${A('صح','right')} · ${g.cnt[1]} ${A('باص','passed')} · ${g.cnt[2]} ${A('ممنوع','taboo')}</p></div>`+(X.C||me?btn(g.n+1>=g.tot?A('النتيجة 🏁','Results 🏁'):A('اللي بعده ⬅','Next ➡'),{t:'next'},'pri'):wait(A('المضيف هيكمّل...','The host will continue...')))}
};

/* ===== Quiz ===== */
G.qz={e:'🧠',cat:3,min:2,lv:'D',R:10,Rmax:30,
 n:()=>A('كويز','Quiz'),Ru:()=>A('الأسئلة','questions'),
 d:()=>A('معلومات عامة ومصر وكورة وفن','General knowledge, Egypt, football, art'),
 h:()=>A('سؤال و4 اختيارات، وكل واحد يجاوب سرّي. في الأوضة معاكم 20 ثانية لكل سؤال. كل إجابة صح بنقطة.','A question with 4 options; everyone answers secretly. In a room you have 20 seconds per question. Each right answer is a point.'),
 start(S,su){const g={dk:shuf(range(QUIZ[su.lvl].length)),n:0,R:su.R};this.beg(g);return g},
 beg(g){g.q=g.dk[g.n%g.dk.length];g.op=shuf([0,1,2,3]);g.ph='q';g.gs=null;coll(g,'q'+g.n,ids());if(App.mode==='room')setT(g,20000);else g.te=0},
 done(g,c){g.gs=c.got;for(const id in c.got)if(c.got[id]===0&&id in g.sc)g.sc[id]++;g.ph='r';g.te=0},
 timeout(g){if(g.ph==='q'&&g.c)skipSoon(g)},
 act(g,a,pid,C,S){if(a.t==='next'&&C&&g.ph==='r'){g.n++;if(g.n>=g.R){finish(S);return}this.beg(g);return}return false},
 view(g,X){const Q=B('QUIZ')[g.lvl][g.q];const h=head(A('سؤال ','Question ')+ofN(g.n+1,g.R))+card(A('سؤال 🧠','Question 🧠'),Q[0],'orng');
  if(g.ph==='q')return h+tmr(g)+cv(g,X,pid=>`<div class="opts">${g.op.map((o,i)=>btn(`<em>${ABCD(i)}</em><span>${esc(Q[1+o])}</span>`,{t:'sub',k:g.c.k,v:o,as:pid},'opt')).join('')}</div>`,{ct:A('جاوب من غير ما حد يشوف 🤫','Answer secretly 🤫'),wt:A('مستنيين الإجابات...','Waiting for answers...')});
  return h+`<div class="opts ro">${g.op.map((o,i)=>`<div class="optr${o===0?' top':''}"><em>${o===0?'✓':ABCD(i)}</em><span>${esc(Q[1+o])}</span><div class="chips">${Object.keys(g.gs||{}).filter(id=>g.gs[id]===o).map(id=>chip(id)).join('')}</div></div>`).join('')}</div>`+nextBtn(g,X,g.n+1>=g.R)}
};

/* ===== Bomb ===== */
G.bm={e:'💣',cat:3,min:2,R:5,Rmax:20,low:1,
 n:()=>A('القنبلة','The bomb'),Ru:()=>A('الجولات','rounds'),
 d:()=>A('قول كلمة ومرّرها قبل ما تفرقع','Say a word and pass it before it blows'),
 h:()=>A('يظهر طلب زي «اسم لاعب كورة»، واللي معاه القنبلة يقول إجابة ويمرّرها بسرعة. القنبلة بتفرقع في وقت عشوائي محدش يعرفه، واللي تفرقع في إيده ياخد نقطة سودا. اللي نقطه السودا أقل هو الكسبان. ممنوع تكرر إجابة اتقالت!','A prompt like "Name a football player" appears; whoever holds the bomb says an answer and passes it fast. It explodes at a random secret moment, and whoever holds it gets a black mark. Fewest marks wins. No repeating answers!'),
 start(S,su){const g={ord:order(),dk:shuf(range(HERD.ar.length)),n:0,R:su.R};this.beg(g);return g},
 beg(g){g.q=g.dk[g.n%g.dk.length];g.ph='rd';g.te=0;g.hd=g.ord[g.n%g.ord.length];g.boom=null},
 nxt(g){const o=g.ord;return o[(o.indexOf(g.hd)+1)%o.length]},
 timeout(g){if(g.ph==='b'){g.boom=g.hd;if(g.hd in g.sc)g.sc[g.hd]++;g.ph='x';g.te=0}},
 act(g,a,pid,C,S){
  if(a.t==='bgo'&&C&&g.ph==='rd'){g.ph='b';g.bs=Date.now();g.cd=0;g.te=g.bs+15000+rint(40000);g.tf=0;g.ps=0;return}
  if(a.t==='bp'&&g.ph==='b'&&(C||pid===g.hd)&&a.f===g.hd){const to=a.to&&a.to in g.sc&&a.to!==g.hd?a.to:this.nxt(g);g.hd=to;g.ps++;return}
  if(a.t==='next'&&C&&g.ph==='x'){g.n++;if(g.n>=g.R){finish(S);return}this.beg(g);return}
  return false},
 view(g,X){const h=head(A('جولة ','Round ')+ofN(g.n+1,g.R))+card(A('قول بسرعة 💣','Quick! 💣'),(EL()?HERD.en:HERD.ar)[g.q],'orng');
  if(g.ph==='rd')return h+`<div class="bomb idle" aria-hidden="true">💣</div><p class="hint">${A('القنبلة هتبدأ مع','The bomb starts with')} ${chip(g.hd)}</p>`+(X.C?btn(A('ولّع الفتيل 🔥','Light the fuse 🔥'),{t:'bgo'},'pri xl'):wait(A('المضيف هيولّع الفتيل...','The host will light the fuse...')));
  if(g.ph==='b'){const mine=X.L||X.me===g.hd;const nx=this.nxt(g);
   return h+`<div class="bomb" data-bs="${g.bs}" aria-hidden="true">💣</div><div class="tb hold">${chip(g.hd)}<small>${A('معاه القنبلة! 😬','has the bomb! 😬')}</small></div>`+(mine?(X.L?btn(A('قلت كلمة؟ مرّرها لـ ','Said it? Pass to ')+esc(nm(nx))+' ➡',{t:'bp',f:g.hd},'pri xl'):`${btn(A('قلت كلمة؟ مرّرها لـ ','Said it? Pass to ')+esc(nm(nx))+' ➡',{t:'bp',f:g.hd},'pri xl')}<p class="hint">${A('أو مرّرها لحد تاني:','or pass to someone else:')}</p><div class="chips pick">${ids().filter(i=>i!==g.hd).map(id=>`<button type="button" class="pc tg" style="--c:${P(id).c}" data-j="${J({t:'bp',f:g.hd,to:id})}">${P(id).e||''} ${esc(nm(id))}</button>`).join('')}</div>`):wait(A('ادعي إنها متفرقعش فيك 🙏','Pray it doesn\'t blow on you 🙏')))}
  return h+`<div class="bomb boom" aria-hidden="true">💥</div><div class="rv"><h3>${A('بوووم! فرقعت في','BOOM! It blew up on')} ${chip(g.boom)}</h3><p class="note">${A('القنبلة اتمرّرت ','Passed ')}${g.ps}${A(' مرة',' times')}</p></div>`+nextBtn(g,X,g.n+1>=g.R)}
};

/* ===== Charades ===== */
G.ch={e:'🎬',cat:3,min:3,lv:'D',R:1,Rmax:4,
 n:()=>A('مثّلها','Charades'),Ru:()=>A('اللفّات','rounds'),
 d:()=>A('مثّل الكلمة من غير كلام','Act it out, no talking'),
 h:()=>A('اللي عليه الدور يشوف كلمة ويمثّلها في دقيقة من غير ولا كلمة ولا صوت، والباقيين يخمّنوا. أول واحد يعرف ياخد نقطة، والممثل ياخد نقطة كمان.','The player whose turn it is sees a word and acts it out within a minute without words or sounds. The first to guess scores, and so does the actor.'),
 start(S,su){const g={ord:order(),t:0,n:0,tot:ids().length*su.R,dk:shuf(range(DRAW[su.lvl].length))};this.beg(g);return g},
 beg(g){g.w=g.dk[g.n%g.dk.length];g.ph='rd';g.te=0;g.cd=0;g.lw=null},
 act(g,a,pid,C,S){const cur=curOf(g);if(!(C||pid===cur))return false;
  if(a.t==='go'&&g.ph==='rd'){g.ph='d';goT(g,60000);return}
  if(a.t==='got'&&g.ph==='d'){g.lw=a.w&&a.w!==cur&&(a.w in g.sc)?a.w:null;if(g.lw){g.sc[g.lw]++;g.sc[cur]++}g.ph='r';g.te=0;return}
  if(a.t==='next'&&g.ph==='r'){g.n++;g.t++;if(g.n>=g.tot){finish(S);return}this.beg(g);return}
  return false},
 view(g,X){const cur=curOf(g),me=X.L||X.me===cur,word=B('DRAW')[g.lvl][g.w],h=turnHead(g,cur);
  if(g.ph==='rd'){if(me)return h+`<div class="curt"><div class="big">🎬</div><h2>${X.L?A('الموبايل مع ','Phone goes to ')+chip(cur):A('دورك تمثّل!','Your turn to act!')}</h2><p>${A('الباقيين ميبصّوش على الشاشة 🙈','No peeking at the screen 🙈')}</p>${btn(A('وريني الكلمة وابدأ ⏱️','Show the word & start ⏱️'),{t:'go'},'pri xl')}</div>`;return h+wait(esc(nm(cur))+A(' بيجهّز...',' is getting ready...'))+(X.C?btn(A('ابدأ بداله','Start for them'),{t:'go'},'ghost sm'):'')}
  const guess=`<p class="hint">${A('مين عرف الأول؟','Who got it first?')}</p><div class="chips pick">${ids().filter(i=>i!==cur).map(id=>`<button type="button" class="pc tg" style="--c:${P(id).c}" data-j="${J({t:'got',w:id})}">${P(id).e||''} ${esc(nm(id))}</button>`).join('')}</div>${btn(A('محدش عرف 😅','Nobody got it 😅'),{t:'got',w:null},'ghost sm')}`;
  if(g.ph==='d'){if(me)return h+cdown(g)+`<article class="qc pink"><span class="tag">${A('مثّل 🎬','Act 🎬')}</span><p class="w">${esc(word)}</p><small>${A('من غير كلام ولا صوت ولا شاورة على حاجة','No words, no sounds, no pointing at things')}</small></article>`+tmr(g)+guess;
   return h+cdown(g)+`<div class="rv"><h3>${chip(cur)} ${A('بيمثّل 🎬','is acting 🎬')}</h3><p>${A('خمّنوا بصوت عالي!','Shout your guesses!')}</p></div>`+tmr(g)+(X.C?guess:'')}
  return h+`<div class="rv"><h3>${A('الكلمة كانت: ','The word was: ')}<b class="w">${esc(word)}</b></h3><p>${g.lw?`${chip(g.lw)} ${A('عرفها! +1 ليه و +1 لـ','got it! +1 to them and +1 to')} ${chip(cur)}`:A('محدش عرف 😅','Nobody got it 😅')}</p></div>`+(X.C||me?btn(g.n+1>=g.tot?A('النتيجة 🏁','Results 🏁'):A('اللي بعده ⬅','Next ➡'),{t:'next'},'pri'):wait(A('المضيف هيكمّل...','The host will continue...')))}
};

/* ===== Who wrote it ===== */
G.wk={e:'📝',cat:0,min:3,lv:'N',R:6,Rmax:20,
 n:()=>A('مين كتب كده؟','Who wrote that?'),Ru:()=>A('الأسئلة','questions'),
 d:()=>A('جاوب سرّي وخمّنوا مين كتب','Answer secretly, guess the writer'),
 h:()=>A('يظهر سؤال صراحة والكل يجاوب من غير أسامي. الموقع يختار إجابة واحد بس ويعرضها، والباقيين يخمّنوا مين كتبها. التخمين الصح بنقطة، وصاحب الإجابة ياخد نقطة عن كل واحد اتضحك عليه.','A truth question appears and everyone answers anonymously. One answer is picked and shown; everyone guesses who wrote it. Right guesses earn a point; the writer earns a point for each person fooled.'),
 start(S,su){const g={dk:shuf(range(TRUTH[su.lvl].length)),n:0,R:su.R};this.beg(g);return g},
 beg(g){g.q=g.dk[g.n%g.dk.length];g.ph='w';g.au=null;g.tx='';g.gs=null;coll(g,'w'+g.n,ids())},
 done(g,c){if(c.k[0]==='w'){const ok=Object.keys(c.got).filter(id=>clean(c.got[id],80));if(ok.length<2){g.ph='r';g.au=null;return}g.au=ok[rint(ok.length)];g.tx=clean(c.got[g.au],80);g.ph='v';coll(g,'v'+g.n,ids().filter(i=>i!==g.au));return}
  g.gs=c.got;let ok=0;for(const id in c.got)if(c.got[id]===g.au&&id in g.sc){g.sc[id]++;ok++}if(g.au in g.sc)g.sc[g.au]+=Object.keys(c.got).length-ok;g.ph='r'},
 act(g,a,pid,C,S){if(a.t==='next'&&C&&g.ph==='r'){g.n++;if(g.n>=g.R){finish(S);return}this.beg(g);return}return false},
 view(g,X){const h=head(A('سؤال ','Question ')+ofN(g.n+1,g.R))+card(A('جاوب بصراحة 🤫','Answer honestly 🤫'),B('TRUTH')[g.lvl][g.q],'pink');
  if(g.ph==='w')return h+cv(g,X,pid=>`<div class="form"><textarea id="wka" maxlength="80" rows="2" placeholder="${A('إجابتك محدش هيعرف إنها بتاعتك... غالبًا 😏','Nobody will know it\'s yours... probably 😏')}"></textarea></div>${ub(A('ابعت 📨','Send 📨'),'wksub',pid,'pri')}`,{ct:A('اكتب إجابتك ومحدش يبص 🤫','Write yours, no peeking 🤫'),wt:A('مستنيين الكل يجاوب...','Waiting for everyone...')});
  const ans=`<article class="qc sun"><span class="tag">${A('واحد فيكم كتب','One of you wrote')}</span><p>«${esc(g.tx)}»</p></article>`;
  if(g.ph==='v')return h+ans+cv(g,X,pid=>`<p class="hint">${A('مين كتب كده؟','Who wrote that?')}</p><div class="grid2">${ids().filter(i=>i!==pid).map(id=>pbtn(id,{t:'sub',k:g.c.k,v:id,as:pid})).join('')}</div>`,{ct:A('خمّن سرّي 🤔','Guess secretly 🤔'),wt:A('مستنيين التخمينات...','Waiting for guesses...')});
  if(!g.au)return h+`<p class="note">${A('مفيش إجابات كفاية 😅','Not enough answers 😅')}</p>`+nextBtn(g,X,g.n+1>=g.R);
  const t=tally(g.gs||{}),tot=Object.values(t).reduce((a,b)=>a+b,0)||1;
  return h+ans+`<div class="rv"><h3>${A('اللي كتبها:','Written by:')} ${chip(g.au)}</h3><div class="bars">${Object.entries(t).sort((a,b)=>b[1]-a[1]).map(([id,n])=>bar(chip(id),n,tot,(P(id)||{}).c)).join('')}</div></div>`+nextBtn(g,X,g.n+1>=g.R)}
};


/* ===== Solo games: one player, no room, no host ===== */
const SOLO={};
const BEST=()=>LS.get('shilla.best',{});
const bestKey=s=>s.id+(SOLO[s.id].lv?'.'+s.lvl:'');
function saveBest(k,v){const b=BEST();if(b[k]!=null&&b[k]>=v)return false;b[k]=v;LS.set('shilla.best',b);return true}
const mcq=(p,opts,tag)=>{const o=shuf(range(opts.length));return{p,tag,o:o.map(i=>opts[i]),a:o.indexOf(0)}};
const fmtN=v=>Number(v).toLocaleString(EL()?'en-US':'ar-EG');
const mmss=ms=>{const t=Math.max(0,Math.floor(ms/1000));return (t/60|0)+':'+String(t%60).padStart(2,'0')};

SOLO.qz={e:'🧠',lv:'D',T:15000,
 n:()=>A('كويز ضد الساعة','Quiz vs the clock'),
 d:()=>A('10 أسئلة، وكل ما تجاوب أسرع نقطك تزيد','10 questions, faster answers score more'),
 h:()=>A('عشر أسئلة معلومات عامة ومعاك 15 ثانية لكل سؤال. الإجابة الصح بـ 10 نقط، وكل ثانية فاضلة بنقطة زيادة، ولو جبت 3 صح ورا بعض تاخد بونص.','Ten trivia questions with 15 seconds each. A right answer is 10 points plus one for every second left, and 3 in a row earns a bonus.'),
 make(s){const Q=B('QUIZ')[s.lvl];return shuf(range(Q.length)).slice(0,10).map(k=>mcq(Q[k][0],Q[k].slice(1),A('سؤال 🧠','Question 🧠')))}};

SOLO.pv={e:'📜',T:15000,
 n:()=>A('كمّل المثل','Finish the proverb'),
 d:()=>A('أول المثل قدامك، اختار آخره','Pick the right ending'),
 h:()=>A('يظهر أول المثل و4 اختيارات لآخره، ومعاك 15 ثانية. كل ما تجاوب أسرع تاخد نقط أكتر.','You see the start of a proverb and 4 endings, with 15 seconds each. Faster answers score more.'),
 make(){const P=PROV[EL()?'en':'ar'];return shuf(range(P.length)).slice(0,10).map(k=>mcq(P[k][0]+' ...',P[k].slice(1),A('كمّل 📜','Finish it 📜')))}};

SOLO.od={e:'🕵️',T:12000,
 n:()=>A('الدخيل','Odd one out'),
 d:()=>A('أربع كلمات، واحدة منهم مش منهم','Four words, one doesn\'t belong'),
 h:()=>A('كل مرة يظهر 4 كلمات: 3 من نفس الفئة وواحدة دخيلة. اكتشفها في 12 ثانية.','Each round shows 4 words: 3 share a category and one is an intruder. Spot it within 12 seconds.'),
 make(){const C=B('SPY');return range(10).map(()=>{for(;;){const a=rint(C.length);let b=rint(C.length-1);if(b>=a)b++;const w=shuf(C[a].w).slice(0,3),x=C[b].w[rint(C[b].w.length)];if(C[a].w.some(y=>nAr(y)===nAr(x)))continue;const q=mcq(A('مين الدخيل؟','Which one doesn\'t belong?'),[x,...w],A('الدخيل 🕵️','Odd one out 🕵️'));q.nt=[x,C[b].n,C[a].n];return q}})}};

SOLO.cl={e:'🔍',lv:'D',T:25000,clue:1,
 n:()=>A('خمّن من الدلايل','Guess from clues'),
 d:()=>A('دلايل بتظهر واحدة واحدة','Clues appear one at a time'),
 h:()=>A('فيه كلمة مستخبية وقدامك دليل واحد عنها. تقدر تكشف لحد 4 دلايل، بس كل دليل زيادة بيقلّل نقطك. معاك 25 ثانية.','A hidden word and one clue about it. You can reveal up to 4 clues, but each extra clue costs points. You have 25 seconds.'),
 make(s){const T=B('TABOO')[s.lvl],ks=shuf(range(T.length));return ks.slice(0,10).map(k=>{const q=mcq(A('الكلمة إيه؟','What\'s the word?'),[T[k][0],...shuf(ks.filter(x=>x!==k)).slice(0,3).map(x=>T[x][0])],A('دلايل 🔍','Clues 🔍'));q.cl=shuf(T[k].slice(1));return q})}};

SOLO.es={e:'🎯',est:1,
 n:()=>A('الأقرب يكسب','Closest wins'),
 d:()=>A('خمّن الرقم، وكل ما تقرّب نقطك تزيد','Guess the number, closer scores more'),
 h:()=>A('8 أسئلة إجابتها رقم. كل سؤال عليه لحد 100 نقطة على حسب انت قريب قد إيه من الإجابة الصح.','8 questions with number answers. Each is worth up to 100 points depending on how close you get.'),
 make(){return shuf(range(EST.ar.length)).slice(0,8).map(k=>({k}))},
 pts(k,v){const a=+EST.ar[k][1];if(/^What year/.test(EST.en[k][0]))return Math.max(0,Math.round(100-Math.abs(v-a)*4));if(!(v>0))return 0;return Math.max(0,Math.round(100*(1-Math.abs(Math.log(v/a))/Math.log(3))))}};

SOLO.mm={e:'🃏',lv:'D',mem:1,
 n:()=>A('الذاكرة','Memory'),
 d:()=>A('اقلب الكروت ولاقي كل اتنين زي بعض','Flip cards and find the pairs'),
 h:()=>A('اقلب كارتين في كل محاولة، ولو طلعوا زي بعض بيفضلوا مفتوحين. خلّص كل الأزواج بأقل عدد محاولات وفي أقل وقت.','Flip two cards per move; matching pairs stay open. Clear the board in as few moves and as little time as you can.'),
 start(s){const P=[6,8,10][s.lvl];const em=shuf(AV).slice(0,P);s.cards=shuf([...em,...em]).map(e=>({e,o:0,d:0}));Object.assign(s,{f:-1,mv:0,t0:0,t1:0,lock:0,pairs:P,nw:-1,qs:null})}};

function soBegin(){const s=App.so,d=SOLO[s.id];Object.assign(s,{i:0,sc:0,ok:0,st:0,bs:0,rec:0,pb:null});if(d.mem){d.start(s);s.ph='q';s.te=0}else{s.qs=d.make(s);soQ()}render(1)}
function soQ(){const s=App.so,d=SOLO[s.id];s.ph='q';s.pick=null;s.gain=0;s.cn=1;s.te=d.T?Date.now()+d.T:0;s.tf=0}
function soAnswer(v){const s=App.so;if(!s||s.ph!=='q'||!s.qs)return;const d=SOLO[s.id];let good,gain=0;
 if(d.est){gain=d.pts(s.qs[s.i].k,v);good=gain>=70}
 else{good=v===s.qs[s.i].a;if(good){const left=s.te?Math.max(0,Math.ceil((s.te-Date.now())/1000)):0;gain=10+left+(s.st>=2?5:0)+(d.clue?(4-s.cn)*5:0)}}
 s.st=good?s.st+1:0;s.bs=Math.max(s.bs,s.st);if(good)s.ok++;s.pick=v;s.gain=gain;s.sc+=gain;s.ph='r';s.te=0;
 SFX.play(good?'ding':'buzz');if(!good)buzz(120);render(1)}
function soNextQ(){const s=App.so;if(!s||s.ph!=='r')return;s.i++;if(s.i>=s.qs.length)soEnd();else soQ();render(1)}
function soEnd(){const s=App.so;s.ph='end';s.te=0;const k=bestKey(s);s.pb=BEST()[k];if(s.pb===undefined)s.pb=null;s.rec=saveBest(k,s.sc)?1:0;
 setTimeout(()=>{SFX.play('win');if(s.rec){SFX.play('cheer');confetti();buzz([60,40,60])}},150)}
function memFlip(i){const s=App.so;if(!s||s.ph!=='q'||!s.cards||s.lock)return;const c=s.cards[i];if(!c||c.o||c.d)return;
 if(!s.t0)s.t0=Date.now();c.o=1;s.nw=i;
 if(s.f<0){s.f=i;render();return}
 const a=s.cards[s.f];s.f=-1;s.mv++;
 if(a.e===c.e){a.d=c.d=1;a.o=c.o=0;SFX.play('coin');
  if(s.cards.every(x=>x.d)){s.t1=Date.now();const sec=Math.round((s.t1-s.t0)/1000);s.sc=Math.max(10,s.pairs*25-(s.mv-s.pairs)*5-Math.floor(sec/2));s.ok=s.pairs;s.lock=1;
   setTimeout(()=>{if(App.so===s){soEnd();render(1)}},700)}
  render();return}
 s.lock=1;render();setTimeout(()=>{a.o=c.o=0;s.lock=0;s.nw=-1;if(App.so===s)render()},850)}

setInterval(()=>{const s=App.so;if(App.mode!=='solo'||!s)return;ticks();
 if(s.ph==='q'&&s.te&&!s.tf&&Date.now()>=s.te){s.tf=1;soAnswer(-1)}
 const el=$('#mmt');if(el&&s.t0&&!s.t1)el.textContent=mmss(Date.now()-s.t0)},300);

/* ---------- solo views ---------- */
function soloMenuV(){const b=BEST();
 return topV(null)+`<main class="wrap"><section class="su"><div class="sue">🎯</div><h1>${A('العب لوحدك','Play solo')}</h1><p class="how">${A('مفيش حد معاك؟ ولا يهمك. اختار لعبة وحاول تكسر رقمك القياسي.','Nobody around? No problem. Pick a game and try to beat your best.')}</p></section><section class="cat vio"><div class="gg">${Object.entries(SOLO).map(([k,d])=>{const bs=Object.keys(b).filter(x=>x===k||x.startsWith(k+'.')).map(x=>b[x]);return `<button type="button" class="gt" data-u="soPick" data-x="${k}"><span class="ge">${d.e}</span><b>${d.n()}</b><small>${d.d()}</small>${bs.length?`<small class="best">🏆 ${Math.max(...bs)}</small>`:''}</button>`}).join('')}</div></section>${ub(A('رجوع','Back'),'soHome','','ghost sm')}</main>`}

function soHead(s){return `<div class="tb"><small>${A('سؤال ','Question ')+ofN(s.i+1,s.qs.length)}</small><small>⭐ <b class="scn">${s.sc}</b>${s.st>=2?` · 🔥 ${s.st}`:''}</small></div>`}
const soNextBtn=s=>ub(s.i+1>=s.qs.length?A('النتيجة 🏁','Results 🏁'):A('التالي ⬅','Next ➡'),'soNext','','pri');

function mcqV(s,d){const q=s.qs[s.i],R=s.ph==='r';
 const clue=d.clue?`<div class="clues">${q.cl.slice(0,R?4:s.cn).map(c=>`<span>${esc(c)}</span>`).join('')}</div>`:'';
 const h=soHead(s)+card(q.tag,q.p,d.clue?'cyan':'orng',clue);
 if(!R)return h+tmr(s)+(d.clue&&s.cn<4?ub(A('دليل كمان 🔍 (−5)','Another clue 🔍 (−5)'),'soClue','','ghost sm'):'')+`<div class="opts">${q.o.map((o,i)=>ub(`<em>${ABCD(i)}</em><span>${esc(o)}</span>`,'soAns',i,'opt')).join('')}</div>`;
 const good=s.pick===q.a;
 return h+`<div class="rv"><h3>${good?`✅ ${A('صح!','Correct!')} <b class="w">+${s.gain}</b>`:s.pick<0?`⏰ ${A('الوقت خلص','Time\'s up')}`:`❌ ${A('غلط','Wrong')}`}</h3>${q.nt?`<p>«${esc(q.nt[0])}» ${A('من فئة','is from')} ${esc(q.nt[1])}${A('، والباقيين',', the rest are')} ${esc(q.nt[2])}</p>`:''}</div><div class="opts ro">${q.o.map((o,i)=>`<div class="optr${i===q.a?' top':''}${i===s.pick&&i!==q.a?' no':''}"><em>${i===q.a?'✓':i===s.pick?'✗':ABCD(i)}</em><span>${esc(o)}</span></div>`).join('')}</div>`+soNextBtn(s)}

function estV(s){const k=s.qs[s.i].k,Q=(EL()?EST.en:EST.ar)[k];const h=soHead(s)+card(A('خمّن 🎯','Guess 🎯'),Q[0],'orng');
 if(s.ph==='q')return h+`<div class="form"><input id="soe${s.i}" inputmode="decimal" autocomplete="off" dir="ltr" placeholder="${A('اكتب رقم','Type a number')}"></div>`+ub(A('ابعت 📨','Send 📨'),'soEst','','pri');
 const c=s.gain>=70?'var(--ok)':s.gain>=40?'var(--sun)':'var(--bad)';
 return h+`<div class="rv"><h3>${A('الإجابة: ','Answer: ')}<b class="w">${fmtN(Q[1])}</b></h3><p>${A('تخمينك: ','Your guess: ')}<b>${fmtN(s.pick)}</b></p><div class="bars">${bar(A('قربك','Closeness'),s.gain,100,c)}</div></div>`+soNextBtn(s)}

function memV(s){const sec=s.t0?(s.t1||Date.now())-s.t0:0,done=s.cards.filter(c=>c.d).length/2;
 return `<div class="tb"><small>${A('محاولات: ','Moves: ')}<b>${s.mv}</b> · ${A('أزواج: ','Pairs: ')}<b>${done}/${s.pairs}</b></small><small>⏱ <b id="mmt">${mmss(sec)}</b></small></div><div class="mem">${s.cards.map((c,i)=>`<button type="button" class="mc${c.o?' up':''}${c.d?' dn':''}${i===s.nw&&c.o?' nw':''}" data-u="soFlip" data-x="${i}"${c.d?' disabled':''} aria-label="${A('كارت ','Card ')}${i+1}">${c.o||c.d?c.e:''}</button>`).join('')}</div>${s.t0?'':`<p class="hint">${A('دوس على أي كارت علشان تبدأ','Tap any card to start')}</p>`}`}

function soEndV(s,d){const st=d.mem?`<span>${A('محاولات','Moves')} <b>${s.mv}</b></span><span>⏱ <b>${mmss(s.t1-s.t0)}</b></span>`:`<span>${A('صح','Correct')} <b>${s.ok}/${s.qs.length}</b></span><span>🔥 ${A('أطول سلسلة','Best streak')} <b>${s.bs}</b></span>`;
 const pb=s.rec?(s.pb!=null?`<p class="note">${A('رقمك اللي فات كان ','Your previous best was ')}${s.pb}</p>`:''):`<p class="note">🏆 ${A('أحسن نتيجة ليك: ','Your best: ')}${s.pb}</p>`;
 return `<section class="res"><div class="sue">${s.rec?'🏆':d.e}</div><h1>${s.rec?A('رقم قياسي جديد!','New record!'):A('خلصت!','Finished!')}</h1><div class="bigsc">⭐ ${s.sc}</div><div class="stats">${st}</div>${pb}${ub(A('العب تاني 🔁','Play again 🔁'),'soGo','','pri xl')}${ub(A('ألعاب تانية','Other games'),'soMenu','','ghost sm')}</section>`}

function soloV(){const s=App.so;if(!s)return soloMenuV();const d=SOLO[s.id],L=d.lv?LVD():null;
 if(s.ph==='su'){const bv=BEST()[bestKey(s)];return topV(null)+`<main class="wrap"><section class="su"><div class="sue">${d.e}</div><h1>${d.n()}</h1><p class="how">${d.h()}</p>${L?`<h3>${A('المستوى','Level')}</h3><div class="lv">${L.map((l,i)=>ub(`${l[1]} ${l[0]}`,'soLvl',i,s.lvl===i?'on':'ghost')).join('')}</div>`:''}${bv!=null?`<p class="note">🏆 ${A('أحسن نتيجة ليك: ','Your best: ')}${bv}</p>`:''}${ub(A('يلا نبدأ 🚀','Start 🚀'),'soGo','','pri xl')}${ub(A('رجوع','Back'),'soMenu','','ghost sm')}</section></main>`}
 const gh=`<div class="gh cat-vio"><span>${d.e}</span><b>${d.n()}</b>${L?`<i>${L[s.lvl][1]} ${L[s.lvl][0]}</i>`:''}</div>`;
 const body=s.ph==='end'?soEndV(s,d):d.mem?memV(s):d.est?estV(s):mcqV(s,d);
 return topV(null)+`<main class="wrap">${s.ph==='end'?'':gh}${body}</main>`}


/* ---------- state + actions ---------- */
function newS(pl){return{v:0,hNow:Date.now(),pl,sc:Object.fromEntries(pl.map(p=>[p.id,0])),scr:'menu',su:null,g:null,res:null,wh:null,nx:1,tmOn:false,ts:[0,0]}}
const inGame=S=>!['menu','su','res','wh'].includes(S.scr);

function finish(S){const g=S.g,d=G[g.id];const I=ids().filter(id=>id in g.sc);
 const sorted=I.slice().sort((a,b)=>d.low?g.sc[a]-g.sc[b]:g.sc[b]-g.sc[a]);
 const rk=[];let pos=0,prev=null;sorted.forEach((id,i)=>{if(prev===null||g.sc[id]!==prev){pos=i;prev=g.sc[id]}rk.push([id,g.sc[id],pos,0])});
 const pts=d.team?[3]:[3,2,1];rk.forEach(r=>{r[3]=pts[r[2]]||0;S.sc[r[0]]=(S.sc[r[0]]||0)+r[3]});
 let tw=null,tt=null;
 if(S.tmOn&&!d.team){tt=[0,0];I.forEach(id=>{const p=P(id);if(p&&p.t!=null)tt[p.t]+=g.sc[id]});if(tt[0]!==tt[1]){tw=d.low?(tt[0]<tt[1]?0:1):(tt[0]>tt[1]?0:1);S.ts[tw]++}}
 let los;if(tw!=null)los=I.filter(id=>P(id)&&P(id).t===1-tw);else{const worst=rk.length?rk[rk.length-1][2]:0;los=rk.filter(r=>r[2]===worst).map(r=>r[0])}
 S.res={id:g.id,rk,lo:los[rint(los.length)]||null,tie:rk.every(r=>r[2]===0)?1:0,tw,tt};S.g=null;S.scr='res'}

function skipSoon(g){const k=g.c&&g.c.k;setTimeout(()=>{const S=App.S;if(S&&S.g===g&&g.c&&g.c.k===k)applyAction({t:'skipc'},App.mode==='local'?null:'p0')},2500)}

function splitTeams(S){shuf(S.pl.map(p=>p.id)).forEach((id,i)=>{P(id).t=i%2})}
function applyAction(a,pid){const S=App.S;if(!S||!a||typeof a.t!=='string')return;const C=App.mode==='local'||pid==='p0';
 try{switch(a.t){
  case 'setup':{if(!C||S.scr!=='menu'||!G[a.id])return;const d=G[a.id];if(S.pl.length<d.min)return;S.su={id:a.id,lvl:d.lv?1:0,R:d.R};S.scr='su';break}
  case 'sulvl':{if(!C||!S.su)return;const L=LVOF(G[S.su.id]);if(!L||!(a.v>=0&&a.v<L.length))return;S.su.lvl=a.v;break}
  case 'suR':{if(!C||!S.su)return;const d=G[S.su.id];S.su.R=Math.max(1,Math.min(d.Rmax,S.su.R+(a.v>0?1:-1)));break}
  case 'start':{if(!C||!S.su)return;const su=S.su,d=G[su.id];if(S.pl.length<d.min)return;const g=d.start(S,su);g.id=su.id;g.lvl=su.lvl;g.sc={};ids().forEach(i=>g.sc[i]=0);S.g=g;S.su=null;S.scr='g';break}
  case 'menu':if(!C)return;S.scr='menu';S.g=null;S.su=null;S.res=null;S.wh=null;break;
  case 'endg':if(!C||!S.g)return;finish(S);break;
  case 'wheel':if(!C||!S.res||!S.res.lo)return;S.wh={lo:S.res.lo,p:null,at:0,tx:null};S.scr='wh';break;
  case 'spin':{if(!C||!S.wh||S.wh.p!=null)return;const pool=[...App.pun.map(t=>({c:t})),...App.pun.map(t=>({c:t})),...range(PUN.length).map(i=>({b:i}))];S.wh.p=rint(8);S.wh.tx=pool[rint(pool.length)];S.wh.at=Date.now();break}
  case 'av':{const p=P(a.id);if(!p||!(C||pid===a.id))return;const ue=new Set(S.pl.map(x=>x.e));const i=AV.indexOf(p.e);for(let k=1;k<=AV.length;k++){const e=AV[(i+k)%AV.length];if(!ue.has(e)){p.e=e;break}}break}
  case 'rstsc':if(!C)return;for(const k in S.sc)S.sc[k]=0;S.ts=[0,0];break;
  case 'tmon':if(!C||inGame(S))return;S.tmOn=true;splitTeams(S);break;
  case 'tmoff':if(!C||inGame(S))return;S.tmOn=false;break;
  case 'tmshuf':if(!C||inGame(S)||!S.tmOn)return;splitTeams(S);break;
  case 'tmsw':{if(!C||inGame(S)||!S.tmOn)return;const p=P(a.id);if(!p)return;p.t=p.t===0?1:0;break}
  case 'sub':{const g=S.g;if(!g||!g.c||g.c.k!==a.k||!g.c.need.includes(pid)||(pid in g.c.got))return;g.c.got[pid]=a.v==null?1:a.v;if(g.c.need.every(i=>i in g.c.got)){const c=g.c;g.c=null;G[g.id].done(g,c,S)}break}
  case 'skipc':{const g=S.g;if(!C||!g||!g.c)return;const c=g.c;c.need=c.need.filter(i=>i in c.got);g.c=null;G[g.id].done(g,c,S);break}
  default:{if(!S.g||!G[S.g.id]||!G[S.g.id].act)return;if(G[S.g.id].act(S.g,a,pid,C,S)===false)return}
 }}catch(e){console.error(e);return}
 commit()}

/* ---------- sync: host keeps the state, phones send actions (PeerJS / WebRTC) ---------- */
const PFX='shilla-eg-v2-';
const NET={peer:null,conns:new Map(),hc:null,tok:{},offAt:{},retry:0,rt:null,restoreUntil:0};
const newCode=()=>range(4).map(()=>CODEL[rint(CODEL.length)]).join('');
const myTok=(()=>{let t=LS.get('shilla.tok',null);if(!t){t=range(16).map(()=>'abcdefghijkmnpqrstuvwxyz23456789'[rint(32)]).join('');LS.set('shilla.tok',t)}return t})();

let saveT=null;
function commit(){const S=App.S;S.v++;S.hNow=Date.now();
 if(App.mode==='local')LS.set('shilla.local',S);render();
 if(App.mode==='room'&&App.host){pub();if(!saveT)saveT=setTimeout(()=>{saveT=null;if(App.host&&App.S)LS.set('shilla.host',{code:App.code,S:App.S,tok:NET.tok,t:Date.now()})},800)}}
let pubT=null;
function pub(){if(pubT)return;pubT=setTimeout(()=>{pubT=null;if(!App.S)return;App.S.hNow=Date.now();const msg={k:'S',S:App.S};for(const c of NET.conns.values()){if(c.open)try{c.send(msg)}catch(e){}}},40)}

function dispatch(a){SFX.play('tap');if(App.mode==='local'){applyAction(a,a.as==null?null:a.as);return}
 if(App.mode!=='room'||!App.S)return;if(App.host){applyAction(a,'p0');return}
 const c=NET.hc;if(!c||!c.open){toast(A('الاتصال بالمضيف مقطوع، بنحاول نرجّعه...','Lost connection to the host, reconnecting...'));return}
 if(a.t==='sub')ui.sent=a.k;delete a.as;try{c.send({k:'a',a})}catch(e){toast(A('مقدرناش نبعت، جرّب تاني','Couldn\'t send, try again'))}render(1)}

function addPl(pr,n){const S=App.S,used=new Set(S.pl.map(x=>x.c));const me=pr===App.myPeer;const id=me?'p0':'p'+(S.nx++);
 const c=COLS.find(c=>!used.has(c))||COLS[rint(COLS.length)];const ue=new Set(S.pl.map(x=>x.e));const pl={id,pr,n,c,e:shuf(AV).find(e=>!ue.has(e))||AV[0]};
 if(S.tmOn){const a=S.pl.filter(p=>p.t===0).length,b=S.pl.filter(p=>p.t===1).length;pl.t=a<=b?0:1}
 if(me)S.pl.unshift(pl);else S.pl.push(pl);if(!(id in S.sc))S.sc[id]=0;return pl}

function prune(){const S=App.S;if(!App.host||!S||inGame(S)||Date.now()<NET.restoreUntil)return;const now=Date.now();
 const gone=S.pl.filter(p=>p.id!=='p0'&&!NET.conns.has(p.pr)&&now-(NET.offAt[p.id]||0)>14000);
 if(gone.length){gone.forEach(p=>{delete S.sc[p.id];delete NET.tok[p.id]});S.pl=S.pl.filter(p=>!gone.includes(p));commit()}}
setInterval(prune,5000);

function onClient(c,d){const S=App.S;if(!S||!d||typeof d!=='object')return;
 if(d.k==='hi'){const n=clean(d.nm,14)||A('لاعب','Player'),tok=clean(d.tok,40);const pid=tok&&Object.keys(NET.tok).find(p=>NET.tok[p]===tok);let pl=pid&&S.pl.find(p=>p.id===pid);
  if(pl){if(pl.pr!==c.peer){const old=NET.conns.get(pl.pr);NET.conns.delete(pl.pr);if(old&&old!==c)try{old.close()}catch(e){}}pl.pr=c.peer;pl.n=n;delete NET.offAt[pl.id]}
  else if(!inGame(S)&&S.pl.length<MAXP){pl=addPl(c.peer,n);if(tok)NET.tok[pl.id]=tok}
  NET.conns.set(c.peer,c);
  if(!pl){try{c.send({k:'S',S});if(S.pl.length>=MAXP)c.send({k:'full'})}catch(e){}return}
  commit();return}
 if(d.k==='a'&&d.a&&typeof d.a==='object'){const pl=S.pl.find(p=>p.pr===c.peer);if(pl&&pl.id!=='p0')applyAction(d.a,pl.id)}}

function onHost(d){if(!d||typeof d!=='object')return;
 if(d.k==='S'&&d.S&&Array.isArray(d.S.pl)){App.S=d.S;App.off=(d.S.hNow||Date.now())-Date.now();App.lost=false;NET.retry=0;render();return}
 if(d.k==='full')toast(A('الأوضة مليانة (20 لاعب)','The room is full (20 players)'))}

function connectHost(){const peer=NET.peer;if(!peer||peer.destroyed)return;const c=peer.connect(PFX+App.code,{reliable:true});NET.hc=c;
 c.on('open',()=>{Object.assign(App,{mode:'room',host:false});NET.retry=0;try{c.send({k:'hi',nm:App.nm,tok:myTok})}catch(e){}LS.set('shilla.client',{code:App.code,t:Date.now()});history.replaceState(null,'','?r='+App.code)});
 c.on('data',onHost);
 c.on('close',()=>{if(NET.hc!==c)return;App.lost=true;render(1);scheduleRetry()});
 c.on('error',()=>{})}

function scheduleRetry(){if(App.host||!App.code||NET.rt)return;if(NET.retry>=60){toast(A('مقدرناش نرجع للأوضة','Couldn\'t get back into the room'));return}
 NET.rt=setTimeout(()=>{NET.rt=null;NET.retry++;if(!App.code||App.host)return;
  if(!NET.peer||NET.peer.destroyed){startPeer(false)}else if(NET.peer.disconnected){try{NET.peer.reconnect()}catch(e){}setTimeout(connectHost,800)}else connectHost();
  setTimeout(()=>{if(!NET.hc||!NET.hc.open)scheduleRetry()},2500)},3000)}

function startPeer(asHost,restore){const code=App.code;const peer=asHost?new Peer(PFX+code):new Peer();NET.peer=peer;
 peer.on('open',id=>{if(NET.peer!==peer)return;App.myPeer=id;
  if(asHost){clearTimeout(NET.fail);if(restore){App.S=restore.S;NET.tok=restore.tok||{};const me=App.S.pl.find(p=>p.id==='p0');if(me){me.pr=id;me.n=App.nm||me.n}NET.restoreUntil=Date.now()+45000;App.S.pl.forEach(p=>{if(p.id!=='p0')NET.offAt[p.id]=Date.now()+30000})}
   else{App.S=newS([]);NET.tok={};addPl(id,App.nm)}
   Object.assign(App,{mode:'room',host:true,lost:false,page:'room'});history.replaceState(null,'','?r='+code);commit();return}
  connectHost()});
 peer.on('connection',c=>{if(!asHost){c.close();return}c.on('data',d=>onClient(c,d));c.on('close',()=>{if(NET.conns.get(c.peer)===c)NET.conns.delete(c.peer);const pl=App.S&&App.S.pl.find(p=>p.pr===c.peer);if(pl)NET.offAt[pl.id]=Date.now();render(1)});c.on('error',()=>{})});
 peer.on('disconnected',()=>{if(NET.peer===peer&&!peer.destroyed)setTimeout(()=>{try{if(!peer.destroyed)peer.reconnect()}catch(e){}},1500)});
 peer.on('error',e=>{if(NET.peer!==peer)return;const t=e&&e.type;
  if(t==='unavailable-id'&&asHost){if(restore){ui.rest=1;render(1);try{peer.destroy()}catch(_){}if((NET.retry++)<40)setTimeout(()=>startPeer(true,restore),3000);else{ui.err=1;render(1)}return}clearTimeout(NET.fail);App.code=newCode();try{peer.destroy()}catch(_){}startPeer(true);return}
  if(t==='peer-unavailable'){if(App.S){App.lost=true;render(1);scheduleRetry();return}clearTimeout(NET.fail);ui.nf=1;render(1);return}
  if(t==='network'||t==='server-error'||t==='socket-error'||t==='socket-closed'){if(!App.S){clearTimeout(NET.fail);ui.err=1;render(1)}else{toast(A('النت فصل لحظة... بنحاول نرجّع الاتصال','Connection dropped... reconnecting'));if(!App.host)scheduleRetry()}}
  else console.warn(e)})}

function enterRoom(code,asHost,restore){if(!navigator.onLine){toast(A('الأوض محتاجة نت 📡 جرّب «موبايل واحد» أو «لوحدك»','Rooms need internet 📡 try One phone or Solo'));return}if(typeof Peer!=='function'){toast(A('مقدرناش نحمّل الاتصال، اتأكد من النت','Couldn\'t load the connection, check your internet'));return}
 if(NET.peer)try{NET.peer.destroy()}catch(e){}NET.conns.clear();NET.hc=null;NET.retry=0;clearTimeout(NET.rt);NET.rt=null;
 App.page='wait';App.code=code;ui.nf=0;ui.err=0;ui.rest=restore?1:0;render(1);
 clearTimeout(NET.fail);NET.fail=setTimeout(()=>{if(App.page==='wait'&&!App.S&&!restore){ui.err=1;render(1)}},15000);
 startPeer(asHost,restore)}

function leave(){clearTimeout(NET.rt);NET.rt=null;App.code='';if(NET.peer)try{NET.peer.destroy()}catch(e){}NET.peer=null;NET.conns.clear();NET.hc=null;
 if(App.host)LS.del('shilla.host');else LS.del('shilla.client');
 Object.assign(App,{page:'home',mode:null,S:null,host:false,lost:false});ui={};try{history.replaceState(null,'',location.pathname)}catch(e){}render(1)}
const shareLink=()=>location.origin+location.pathname+'?r='+App.code;

/* ---------- views ---------- */
function topV(X){return `<header class="top"><span class="logo">${A('الشلّة','Shilla')}</span>${App.mode==='room'?`<span class="rc" title="${A('كود الأوضة','Room code')}">${esc(App.code)}</span>`:''}<span class="sp"></span>${ub(App.mute?'🔇':'🔊','mute','','ic')}${ub(EL()?'ع':'EN','lang','','ic')}${App.S?ub('🏆','lb','','ic'):''}${X&&X.C&&App.S&&App.S.scr!=='menu'?btn('🎮',{t:'menu'},'ic'):''}${App.mode?ub(ui.ex?A('متأكد؟','Sure?'):A('خروج','Exit'),'exit','','ic'+(ui.ex?' bad':'')):''}</header>`}

function homeV(){const saved=LS.get('shilla.local',null);const n=Object.keys(G).length;return topV(null)+`<main class="wrap home">
<section class="hero"><div class="floaters" aria-hidden="true">${['🎭','💣','🐺','🎨','🕵️','🎡','😳','🔥','🧠','🙋'].map((e,i)=>`<span style="--i:${i}">${e}</span>`).join('')}</div><div class="dice" aria-hidden="true"><span>🎲</span><span>🃏</span><span>🎯</span></div><h1 class="brand">${A('الشلّة','Shilla')}</h1><p class="tagl">${A(`${n} لعبة للقعدة: صراحة، تصويت، جاسوس، مافيا، رسم، وكويز.`,`${n} party games: truth, voting, spies, mafia, drawing, and trivia.`)}</p></section>
<div class="modes"><article class="mode pink"><span class="mi">📱</span><h2>${A('موبايل واحد','One phone')}</h2><p>${A('تكتبوا أساميكم والموبايل يلف عليكم.','Add your names and pass the phone around.')}</p>${ub(A('يلا بينا','Let\'s go'),'go','lsetup','pri')}${saved&&saved.pl?ub(A('كمّل السهرة اللي فاتت','Continue last night'),'resume','','ghost sm'):''}</article>
<article class="mode cyan"><span class="mi">📲</span><h2>${A('أوضة بكود','Room with a code')}</h2><p>${A('كل واحد يدخل من موبايله، لحد 20 لاعب.','Everyone joins from their own phone, up to 20 players.')}</p>${!navigator.onLine?`<p class="warn">📡 ${A('انت مش متوصل بالنت دلوقتي. الأوض محتاجة نت، بس «موبايل واحد» و«لوحدك» شغالين عادي.','You\'re offline. Rooms need internet, but One phone and Solo work fine.')}</p>`:App.roomOK===false?`<p class="warn">${A('الأوض محتاجة نت. اتأكد إنك متوصّل وحدّث الصفحة.','Rooms need internet. Check your connection and refresh.')}</p>`:`<div class="row">${ub(A('اعمل أوضة','Create room'),'go','rmk','pri')}${ub(A('ادخل بكود','Join with code'),'go','rjn','ghost')}</div>`}</article>
<article class="mode vio solo"><span class="mi">🎯</span><h2>${A('لوحدك','Solo')}</h2><p>${A(`مفيش حد معاك؟ ${Object.keys(SOLO).length} ألعاب تلعبها لوحدك وتكسر فيها رقمك القياسي.`,`Nobody around? ${Object.keys(SOLO).length} games to play alone and beat your best score.`)}</p>${ub(A('العب لوحدك','Play solo'),'solo','','pri')}</article></div>
${INST.ev?`<div class="inst">${ub(A('📲 ثبّت الشلّة على موبايلك وتشتغل من غير نت','📲 Install Shilla, it works offline'),'install','','ghost')}</div>`:''}
<section class="cats">${CATS().map((c,i)=>`<div class="cl ${c.c}"><b>${c.n}</b><span>${Object.values(G).filter(d=>d.cat===i).map(d=>d.e+' '+d.n()).join(' · ')}</span></div>`).join('')}<div class="cl vio"><b>${A('لوحدك','Solo')}</b><span>${Object.values(SOLO).map(d=>d.e+' '+d.n()).join(' · ')}</span></div></section></main>`}

function lsV(){const sv=LS.get('shilla.lp',[]);if(!ui.lv)ui.lv=sv.length?sv.slice():['','',''];const n=Math.max(2,ui.lv.length);
 return topV(null)+`<main class="wrap"><section class="su"><h1>${A('مين هيلعب؟','Who\'s playing?')}</h1><p class="how">${A('من 2 لـ 20 لاعب.','2 to 20 players.')}</p><div class="form">${range(n).map(i=>`<label class="fl2"><span>${i+1}</span><input id="ln${i}" maxlength="14" autocomplete="off" placeholder="${A('اسم اللاعب','Player name')}" value="${esc(ui.lv[i]||'')}">${n>2?`<button type="button" class="x" data-u="lrm" data-x="${i}" aria-label="${A('شيل اللاعب','Remove')}">✕</button>`:''}</label>`).join('')}</div>${n<MAXP?ub(A('+ لاعب كمان','+ Add player'),'ladd','','ghost'):''}${ub(A('يلا نبدأ 🎉','Start 🎉'),'lstart','','pri xl')}${ub(A('رجوع','Back'),'go','home','ghost sm')}</section></main>`}

function rmkV(){return topV(null)+`<main class="wrap"><section class="su"><h1>${A('اعمل أوضة','Create a room')}</h1><p class="how">${A('هيطلعلك لينك وكود من 4 حروف، تبعتهم للشلة ويدخلوا من موبايلاتهم.','You\'ll get a link and a 4-letter code to send to your friends.')}</p><div class="form"><label class="fl2"><span>${A('اسمك','Name')}</span><input id="rn" maxlength="14" autocomplete="off" value="${esc(App.nm)}" placeholder="${A('اسمك','Your name')}"></label></div>${ub(A('اعمل الأوضة 🚪','Create 🚪'),'rmk','','pri xl')}${ub(A('رجوع','Back'),'go','home','ghost sm')}</section></main>`}
function rjnV(){return topV(null)+`<main class="wrap"><section class="su"><h1>${A('ادخل أوضة','Join a room')}</h1><p class="how">${A('اكتب اسمك والكود اللي معاك.','Enter your name and the room code.')}</p><div class="form"><label class="fl2"><span>${A('اسمك','Name')}</span><input id="rn" maxlength="14" autocomplete="off" value="${esc(App.nm)}" placeholder="${A('اسمك','Your name')}"></label><label class="fl2"><span>${A('الكود','Code')}</span><input id="rc" class="codein" maxlength="4" autocomplete="off" autocapitalize="characters" dir="ltr" placeholder="ABCD" value="${esc(App.jc||'')}"></label></div>${ub(A('ادخل 🚪','Join 🚪'),'rjn','','pri xl')}${ub(A('رجوع','Back'),'go','home','ghost sm')}</section></main>`}
function waitV(){return topV(null)+`<main class="wrap"><section class="su">${ui.err?`<h1>${A('مقدرناش نتصل 😕','Couldn\'t connect 😕')}</h1><p class="how">${A('اتأكد إن النت شغال وجرّب تاني. لو الشبكة بتاعة شغل أو جامعة، جرّب بيانات الموبايل.','Check your internet and try again. On work or university wifi, try mobile data.')}</p>${ub(A('رجوع','Back'),'exit2','','pri')}`:ui.nf?`<h1>${A('ملقيناش الأوضة 😕','Room not found 😕')}</h1><p class="how">${A('اتأكد من الكود','Check the code')} <b dir="ltr">${esc(App.code)}</b>${A('، وإن اللي عامل الأوضة لسه فاتح الصفحة.',', and that the host still has the page open.')}</p>${ub(A('جرّب تاني','Try again'),'exit2','','pri')}`:`<h1>${ui.rest?A('بنرجّع الأوضة...','Restoring the room...'):A('بندخّلك الأوضة...','Joining the room...')}</h1>${wait(A('ثانية واحدة','One moment'))}`}</section></main>`}

function menuV(X){const S=App.S;
 const code=App.mode==='room'?`<section class="code"><small>${A('كود الأوضة','Room code')}</small><div class="cd" dir="ltr">${[...App.code].map(c=>`<b>${c}</b>`).join('')}</div><p>${A('ابعتوا اللينك للشلة وهيدخلوا الأوضة على طول.','Send the link and friends jump straight in.')}</p><div class="row">${ub(A('ابعت اللينك 📤','Share link 📤'),'share','','pri sm')}${ub(A('انسخ اللينك','Copy link'),'copy','','ghost sm')}</div></section>`:'';
 const pc=p=>{const off=App.host&&p.id!=='p0'&&!NET.conns.has(p.pr);return chip(p.id,(p.id==='p0'&&App.mode==='room'?' 👑':'')+(off?' 📡':''))};
 const tm=S.tmOn?`<div class="teams">${[0,1].map(t=>`<div class="team t${t}"><h4>${tName(t)} <small>${S.ts[t]?'🏆 '+S.ts[t]:''}</small></h4><div class="chips">${S.pl.filter(p=>p.t===t).map(p=>X.C?`<button type="button" class="pcb" data-j="${J({t:'tmsw',id:p.id})}">${pc(p)}</button>`:pc(p)).join('')}</div></div>`).join('')}</div>${X.C?`<p class="note">${A('دوس على أي اسم علشان تنقله للفريق التاني','Tap a name to move them to the other team')}</p>`:''}`:`<div class="chips">${S.pl.map(p=>X.L?`<button type="button" class="pcb" data-j="${J({t:'av',id:p.id})}">${pc(p)}</button>`:pc(p)).join('')}</div>`;
 const myAv=X.me&&!S.tmOn?`<div class="myav">${btn(A('غيّر شكلك ','Change avatar ')+((P(X.me)||{}).e||'🙂'),{t:'av',id:X.me},'ghost sm')}</div>`:(X.L&&!S.tmOn?`<p class="note">${A('دوس على أي لاعب علشان تغيّر شكله','Tap a player to change their avatar')}</p>`:'');
 const pl=`<section class="pls"><div class="plh"><h3>${A('الشلة','Players')} (${S.pl.length}/${MAXP})</h3>${X.C?(S.tmOn?`<div class="row">${btn(A('لخبط الفرق 🔀','Shuffle 🔀'),{t:'tmshuf'},'ghost sm')}${btn(A('من غير فرق','No teams'),{t:'tmoff'},'ghost sm')}</div>`:btn(A('قسّمونا فرق 👥','Split into teams 👥'),{t:'tmon'},'ghost sm',S.pl.length<4)):''}</div>${tm}${myAv}</section>`;
 const games=CATS().map((c,ci)=>`<section class="cat ${c.c}"><h2>${c.n}</h2><div class="gg">${Object.entries(G).filter(([,d])=>d.cat===ci).map(([k,d])=>{const ok=S.pl.length>=d.min;return `<button type="button" class="gt" ${X.C&&ok?`data-j="${J({t:'setup',id:k})}"`:'disabled'}><span class="ge">${d.e}</span><b>${d.n()}</b><small>${ok?d.d():A('محتاجة '+d.min+' على الأقل','Needs at least '+d.min)}</small></button>`}).join('')}</div></section>`).join('');
 const pun=X.C?`<section class="punb"><h2>${A('عقابات الشلة 😈','Your punishments 😈')}</h2><p class="how">${A('ضيفوا عقاباتكم، وهتدخل في عجلة العقاب جنب العقابات الجاهزة.','Add your own; they join the built-in ones on the punishment wheel.')}</p><div class="addr"><input id="pn" maxlength="60" autocomplete="off" placeholder="${A('مثلًا: يعزم الشلة على كشري','e.g. buys everyone koshari')}">${ub(A('ضيف','Add'),'padd','','pri')}</div>${App.pun.length?`<ul class="pul">${App.pun.map((t,i)=>`<li><span>${esc(t)}</span><button type="button" class="x" data-u="pdel" data-x="${i}" aria-label="${A('امسح','Delete')}">✕</button></li>`).join('')}</ul>`:''}</section>`:'';
 return code+pl+(X.C?`<h1 class="pick">${A('اختاروا لعبة','Pick a game')}</h1>`:wait(A('المضيف بيختار لعبة...','The host is picking a game...')))+games+pun}

function suV(X){const su=App.S.su,d=G[su.id],L=LVOF(d);
 return `<section class="su"><div class="sue">${d.e}</div><h1>${d.n()}</h1><p class="how">${d.h()}</p>${L?`<h3>${A('المستوى','Level')}</h3><div class="lv">${X.C?L.map((l,i)=>btn(`${l[1]} ${l[0]}`,{t:'sulvl',v:i},su.lvl===i?'on':'ghost')).join(''):`<span class="lvs">${L[su.lvl][1]} ${L[su.lvl][0]}</span>`}</div>`:''}${d.noR?'':`<h3>${A('عدد ','Number of ')}${d.Ru()}</h3><div class="step">${X.C?btn('−',{t:'suR',v:-1},'ghost'):''}<b>${su.R}</b>${X.C?btn('+',{t:'suR',v:1},'ghost'):''}</div>`}${App.S.tmOn&&!d.team?`<p class="note">👥 ${A('النقط هتتجمع للفريقين','Points add up per team')}</p>`:''}${X.C?btn(A('يلا نبدأ 🚀','Start 🚀'),{t:'start'},'pri xl')+btn(A('رجوع','Back'),{t:'menu'},'ghost sm'):wait(A('المضيف بيظبط اللعبة...','The host is setting up...'))}</section>`}

function resV(X){const r=App.S.res,d=G[r.id];
 const team=r.tt?`<div class="tres">${[0,1].map(t=>`<div class="team t${t}${r.tw===t?' win':''}"><h4>${tName(t)}</h4><b>${r.tt[t]}</b></div>`).join('')}</div><p class="note">${r.tw==null?A('الفريقين متعادلين!','The teams are tied!'):tName(r.tw)+A(' كسب 🎉',' wins 🎉')}</p>`:'';
 return `<section class="res"><div class="sue">${d.e}</div><h1>${A('خلصت ','Finished: ')}${d.n()}</h1>${d.low?`<p class="note">${A('في اللعبة دي اللي فضايحه أقل هو الكسبان','In this game, fewest scandals wins')}</p>`:''}${team}<ol class="rk">${r.rk.map(([id,s,pos,pt])=>`<li class="${pos===0?'w':''}${id===r.lo?' lo':''}"><span class="pos">${['🥇','🥈','🥉'][pos]||pos+1}</span>${chip(id)}<b>${s}</b><em>${pt?'+'+pt+' 🏆':''}</em></li>`).join('')}</ol>${r.lo?`<div class="lose"><p>${r.tw!=null?A('من الفريق الخسران:','From the losing team:'):r.tie?A('كلكم متعادلين! اللي عليه العقاب:','All tied! Punishment goes to:'):A('آخر واحد:','Last place:')} ${chip(r.lo)}</p><p>${A('العقاب مستنيك 😈','Your punishment awaits 😈')}</p></div>`:''}${X.C?(r.lo?btn(A('لفّ عجلة العقاب 🎡','Spin the punishment wheel 🎡'),{t:'wheel'},'pri xl'):'')+btn(A('نعدّيها ونرجع للألعاب','Skip, back to games'),{t:'menu'},'ghost sm'):wait(A('المضيف هيلفّ العجلة...','The host will spin the wheel...'))}</section>`}

function whV(X){const w=App.S.wh,seg=45,sp=w.p!=null,el=sp?Date.now()+offNow()-w.at:0,done=sp&&el>4400,ang=sp?360*6-(w.p+.5)*seg:0;
 const tx=w.tx?(w.tx.c!=null?w.tx.c:B('PUN')[w.tx.b]):'';
 return `<section class="whs"><h1>${A('عجلة العقاب 🎡','Punishment wheel 🎡')}</h1><p class="how">${A('لـ','For')} ${chip(w.lo)}</p><div class="wheel"><div class="ptr"></div><div class="wd" data-ang="${ang}" data-at="${w.at}">${WE.map((e,i)=>`<span style="--r:${(i+.5)*seg}deg">${e}</span>`).join('')}</div><div class="hub">😈</div></div>${done?card(A('العقاب 😈','Punishment 😈'),tx,'pink'):''}${!sp?(X.C?btn(A('لفّ! 🎡','Spin! 🎡'),{t:'spin'},'pri xl'):wait(A('المضيف هيلفّ...','The host will spin...'))):(done&&X.C?btn(A('رجوع للألعاب 🎮','Back to games 🎮'),{t:'menu'},'pri'):'')}</section>`}

function lbV(X){const S=App.S,rows=S.pl.slice().sort((a,b)=>(S.sc[b.id]||0)-(S.sc[a.id]||0));
 return `<div class="ov"><button type="button" class="ovbg" data-u="lb" aria-label="${A('قفل','Close')}"></button><div class="ovc" role="dialog" aria-label="${A('ترتيب السهرة','Leaderboard')}"><h2>🏆 ${A('ترتيب السهرة','Tonight\'s leaderboard')}</h2>${S.tmOn?`<div class="tres">${[0,1].map(t=>`<div class="team t${t}"><h4>${tName(t)}</h4><b>${S.ts[t]}</b><small>${A('لعبة كسبها','games won')}</small></div>`).join('')}</div>`:''}<ol class="rk">${rows.map((p,i)=>`<li class="${i===0&&(S.sc[p.id]||0)>0?'w':''}"><span class="pos">${i+1}</span>${chip(p.id)}<b>${S.sc[p.id]||0}</b></li>`).join('')}</ol><p class="note">${A('الأول في أي لعبة +3، التاني +2، التالت +1','1st in any game +3, 2nd +2, 3rd +1')}</p><div class="row">${X.C?(ui.rs?btn(A('أيوه صفّر 🗑️','Yes, reset 🗑️'),{t:'rstsc'},'bad sm'):ub(A('صفّر النقط','Reset points'),'rs','','ghost sm')):''}${ub(A('قفل','Close'),'lb','','ghost sm')}</div></div></div>`}

function view(){const S=App.S;
 const key=App.page+'|'+App.mode+'|'+(S?S.scr+'|'+(S.g?[S.g.id,S.g.ph,S.g.n,S.g.t,S.g.day].join(','):''):'')+(App.so?'|'+[App.so.id,App.so.ph,App.so.i].join(','):'');
 if(key!==uiKey){ui={lb:ui.lb,lv:ui.lv,nf:ui.nf,err:ui.err,rest:ui.rest};uiKey=key;App.anim=1}
 if(App.mode==='solo')return soloV();
 if(!App.mode||!S){if(App.page==='lsetup')return lsV();if(App.page==='rmk')return rmkV();if(App.page==='rjn')return rjnV();if(App.page==='wait'||App.mode==='room')return waitV();return homeV()}
 App.me=App.mode==='room'?(App.host?'p0':((S.pl.find(p=>p.pr===App.myPeer)||{}).id||null)):null;
 const X={S,L:App.mode==='local',C:App.mode==='local'||App.host,me:App.me};
 let body;
 if(S.scr==='menu')body=menuV(X);else if(S.scr==='su'&&S.su)body=suV(X);else if(S.scr==='res'&&S.res)body=resV(X);else if(S.scr==='wh'&&S.wh)body=whV(X);
 else if(S.g&&G[S.g.id]){const d=G[S.g.id],L=LVOF(d);const sc=S.g.sc||{},top=d.team?[]:Object.keys(sc).sort((a,b)=>d.low?sc[a]-sc[b]:sc[b]-sc[a]).slice(0,3);body=`<div class="gh cat-${CATS()[d.cat].c}"><span>${d.e}</span><b>${d.n()}</b>${L?`<i>${L[S.g.lvl][1]} ${L[S.g.lvl][0]}</i>`:''}</div>`+(top.length&&Object.values(sc).some(v=>v)?`<div class="mini">${top.map((id,i)=>`<span>${['🥇','🥈','🥉'][i]} ${(P(id)||{}).e||''} ${esc(nm(id))} <b>${sc[id]}</b></span>`).join('')}${X.me&&!top.includes(X.me)&&X.me in sc?`<span class="me">${A('انت','You')} <b>${sc[X.me]}</b></span>`:''}</div>`:'')+d.view(S.g,X)+(X.C?`<div class="endg">${ui.eg?btn(A('أيوه، اقفل اللعبة وطلّع النتيجة','Yes, end it and show results'),{t:'endg'},'bad sm'):ub(A('إنهاء اللعبة','End game'),'eg','','ghost sm')}</div>`:'')}
 else body=wait('...');
 const notes=(App.lost?`<div class="dead">${App.host?A('النت فصل عندك، بنحاول نرجّعه...','Your connection dropped, reconnecting...'):A('الاتصال بالمضيف فصل، بنرجّعك تلقائي... 📡','Lost the host, reconnecting automatically... 📡')}</div>`:'')+(App.mode==='room'&&!App.host&&!App.me&&S.g?`<div class="dead">${A('انت داخل وسط لعبة 👀 هتلعب معانا في اللي جاية','You joined mid-game 👀 you\'ll play in the next one')}</div>`:'');
 return topV(X)+`<main class="wrap">${notes}${body}</main>`+(ui.lb?lbV(X):'')}

let lastSig='',lastTe=0;
function render(force,noKeep){let html;try{html=view()}catch(e){console.error(e);html=`<main class="wrap"><div class="dead">${A('حصلت مشكلة في العرض 😕','Something went wrong 😕')}</div>${ub(A('ارجع للبداية','Back to start'),'exit2','','pri')}</main>`}
 if(!force&&html===App.last)return;
 const keep={};if(!noKeep)document.querySelectorAll('#app input,#app textarea').forEach(el=>{if(el.id)keep[el.id]={v:el.value,c:el.checked}});
 const fid=document.activeElement&&document.activeElement.id;
 $('#app').innerHTML=html;App.last=html;if(App.anim){App.anim=0;const m=$('#app main');if(m&&m.classList)m.classList.add('anim')}
 for(const id in keep){const el=document.getElementById(id);if(!el)continue;if(el.type==='radio'||el.type==='checkbox')el.checked=keep[id].c;else el.value=keep[id].v}
 if(fid&&!noKeep){const f=document.getElementById(fid);if(f&&f.tagName!=='BUTTON')f.focus()}
 after()}

let lastMy=null;
function fx(){const S=App.S;if(!S)return;const g=S.g;
 if(App.mode==='room'&&App.me&&g&&g.sc&&App.me in g.sc){const k=g.id+'|'+S.v,v=g.sc[App.me];if(lastMy&&lastMy.id===g.id&&v>lastMy.v)scorePop('+'+(v-lastMy.v));lastMy={id:g.id,v}}else if(!g)lastMy=null;
 const sig=S.scr+'|'+(g?g.id+g.ph+(g.n||0)+(g.t||0)+(g.day||0):'')+'|'+(S.wh&&S.wh.p!=null?'s':'');
 if(sig===lastSig)return;const prev=lastSig;lastSig=sig;if(!prev)return;
 const X={L:App.mode==='local',me:App.me};
 if(S.scr==='res'&&!prev.startsWith('res')){SFX.play('drum');setTimeout(()=>{SFX.play('win');SFX.play('cheer');confetti()},1300);buzz([60,40,60])}
 else if(S.scr==='wh'&&S.wh&&S.wh.p!=null&&!prev.endsWith('|s'))SFX.play('spin');
 else if(g&&g.id==='fw'&&g.ph==='sh')SFX.play('spin');
 else if(g&&g.id==='bm'&&g.ph==='x'){SFX.play('boom');buzz([300,80,300])}
 else if(g&&/^(r|end|dr|sg|s)$/.test(g.ph))SFX.play('ding');
 else if(g&&!X.L&&inInput(g,{L:false,me:App.me})){SFX.play('turn');buzz(80)}
 else SFX.play('whoosh')}
function scorePop(t){const el=document.createElement('div');el.className='spop';el.textContent=t+' ⭐';document.body.appendChild(el);SFX.play('coin');setTimeout(()=>el.remove(),1600)}
let whShown=0,cdLast='';
function after(){initCanvas();ticks();fx();const wd=$('.wd');if(wd){const ang=+wd.dataset.ang;if(ang){const el=Date.now()+offNow()-(+wd.dataset.at);const red=matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(el<4000&&!red){wd.style.transition='none';wd.style.transform='rotate(0deg)';requestAnimationFrame(()=>requestAnimationFrame(()=>{wd.style.transition=`transform ${Math.max(.4,(4200-el)/1000)}s cubic-bezier(.15,.7,.2,1)`;wd.style.transform=`rotate(${ang}deg)`}))}else wd.style.transform=`rotate(${ang}deg)`}}}

function ticks(){const now=Date.now()+offNow();document.querySelectorAll('[data-te]').forEach(el=>{const s=Math.max(0,Math.ceil((+el.dataset.te-now)/1000));el.querySelector('b').textContent=(s/60|0)+':'+String(s%60).padStart(2,'0');el.classList.toggle('low',s<=10&&s>0);el.classList.toggle('over',s===0);
 const k=el.dataset.te+'|'+s;if(k!==lastTe){lastTe=k;if(s>0&&s<=5)SFX.play('tick');else if(s===0&&el.dataset.bz!=='1'){el.dataset.bz='1';SFX.play('buzz')}}})}

setInterval(()=>{const S=App.S;if(!S||!App.mode)return;ticks();const g=S.g,now=Date.now()+offNow();
 if(g&&g.te&&now>=g.te){if(App.mode==='room')autoSub(g);if((App.mode==='local'||App.host)&&!g.tf){g.tf=1;const d=G[g.id];if(d.timeout)d.timeout(g,S);commit()}}
 if(S.scr==='wh'||(g&&g.id==='fw'&&g.ph==='sh')||(g&&g.cd&&now<g.cd+400))render();
 if(S.scr==='wh'&&S.wh&&S.wh.p!=null){const done=now-S.wh.at>4400;if(done&&whShown!==S.wh.at){whShown=S.wh.at;SFX.play('sad');buzz(200)}}
 const cd=$('.cdown');if(cd){const n=Math.max(1,Math.ceil((+cd.dataset.cd-now)/1000));const b=cd.querySelector('b');if(b&&b.textContent!==String(n)){b.textContent=n;b.style.animation='none';void b.offsetWidth;b.style.animation=''}if(cdLast!==cd.dataset.cd+n){cdLast=cd.dataset.cd+n;SFX.play('tick');buzz(30)}}},300);
let bombT=0;setInterval(()=>{const el=$('.bomb[data-bs]');if(!el)return;const now=Date.now()+offNow(),e=now-(+el.dataset.bs),per=Math.max(180,900-e/45);el.style.setProperty('--sp',per/1000+'s');if(now-bombT>per){bombT=now;SFX.play('tick')}},90);

function autoSub(g){const c=g.c;if(!c||g.id!=='lt'||!App.me)return;if(!c.need.includes(App.me)||App.me in c.got||ui.sent===c.k||ui.auto===c.k)return;ui.auto=c.k;UI.ltsub(App.me)}

/* ---------- canvas ---------- */
function initCanvas(){const cv=$('#cv');if(!cv||cv._i)return;cv._i=1;const r=cv.getBoundingClientRect(),d=window.devicePixelRatio||1;cv.width=Math.round(r.width*d);cv.height=Math.round(r.height*d);const x=cv.getContext('2d');x.scale(d,d);x.lineCap='round';x.lineJoin='round';x.fillStyle='#fffdf7';x.fillRect(0,0,r.width,r.height);
 let dn=false,lx=0,ly=0;const pos=e=>{const b=cv.getBoundingClientRect();return[e.clientX-b.left,e.clientY-b.top]};
 const st=()=>{const er=App.pen==='er';x.strokeStyle=er?'#fffdf7':App.pen;x.lineWidth=er?22:5};
 cv.addEventListener('pointerdown',e=>{e.preventDefault();dn=true;try{cv.setPointerCapture(e.pointerId)}catch(_){}[lx,ly]=pos(e);st();x.beginPath();x.moveTo(lx,ly);x.lineTo(lx+.01,ly);x.stroke()});
 cv.addEventListener('pointermove',e=>{if(!dn)return;const[nx,ny]=pos(e);st();x.beginPath();x.moveTo(lx,ly);x.lineTo(nx,ny);x.stroke();lx=nx;ly=ny});
 ['pointerup','pointercancel','pointerleave'].forEach(t=>cv.addEventListener(t,()=>dn=false))}

/* ---------- UI handlers ---------- */
const readLn=()=>{const out=[];for(let i=0;i<MAXP;i++){const el=document.getElementById('ln'+i);if(!el)break;out.push(el.value)}return out};
const val=id=>($('#'+id)||{}).value;
const UI={
 install(){const ev=INST.ev;if(!ev)return;INST.ev=null;ev.prompt();(ev.userChoice||Promise.resolve()).then(()=>render(1))},
 solo(){App.mode='solo';App.so=null;ui={};render(1)},
 soHome(){App.mode=null;App.so=null;App.page='home';ui={};render(1)},
 soMenu(){App.so=null;render(1)},
 soPick(x){const d=SOLO[x];if(!d)return;App.so={id:x,ph:'su',lvl:d.lv?1:0};render(1)},
 soLvl(x){if(App.so&&App.so.ph==='su'){App.so.lvl=+x;render()}},
 soGo(){if(App.so)soBegin()},
 soAns(x){soAnswer(+x)},
 soClue(){const s=App.so;if(s&&s.ph==='q'&&s.cn<4){s.cn++;SFX.play('pop');render()}},
 soNext(){soNextQ()},
 soEst(){const s=App.so;if(!s||s.ph!=='q')return;const raw=String(val('soe'+s.i)||'').replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[,،\s]/g,'').replace('٫','.');const v=parseFloat(raw);if(!isFinite(v))return toast(A('اكتب رقم','Type a number'));soAnswer(v)},
 soFlip(x){memFlip(+x)},
 go(x){App.page=x;ui.lv=null;render(1)},
 ladd(){ui.lv=readLn();if(ui.lv.length<MAXP)ui.lv.push('');render(1,1);const el=document.getElementById('ln'+(ui.lv.length-1));if(el)el.focus()},
 lrm(x){ui.lv=readLn();ui.lv.splice(+x,1);while(ui.lv.length<2)ui.lv.push('');render(1,1)},
 lstart(){const names=readLn().map(s=>clean(s,14)).filter(Boolean);if(names.length<2)return toast(A('محتاجين اتنين على الأقل','You need at least two players'));if(new Set(names).size!==names.length)return toast(A('فيه اسمين شبه بعض، غيّر واحد فيهم','Two names are the same, change one'));LS.set('shilla.lp',names);const av=shuf(AV);const pl=names.map((n,i)=>({id:'p'+i,n,c:COLS[i%COLS.length],e:av[i%av.length]}));App.mode='local';App.host=false;App.S=newS(pl);App.S.nx=pl.length;commit()},
 resume(){const s=LS.get('shilla.local',null);if(s&&Array.isArray(s.pl)){if(!s.ts)s.ts=[0,0];App.mode='local';App.S=s;render(1)}},
 rmk(){const n=clean(val('rn'),14);if(!n)return toast(A('اكتب اسمك الأول','Enter your name first'));App.nm=n;LS.set('shilla.nm',n);LS.del('shilla.host');enterRoom(newCode(),true)},
 rjn(){const n=clean(val('rn'),14),c=clean(val('rc'),4).toUpperCase();if(!n)return toast(A('اكتب اسمك الأول','Enter your name first'));if(!/^[A-Z]{4}$/.test(c))return toast(A('الكود 4 حروف إنجليزي','The code is 4 letters'));App.nm=n;LS.set('shilla.nm',n);enterRoom(c,false)},
 share(){const url=shareLink();if(navigator.share){navigator.share({title:A('الشلّة','Shilla'),text:A('تعالى العب معانا في الشلّة! كود الأوضة: ','Come play Shilla with us! Room code: ')+App.code,url}).catch(()=>{})}else UI.copy()},
 copy(){const url=shareLink();const done=()=>toast(A('اتنسخ اللينك ✓','Link copied ✓'));if(navigator.clipboard)navigator.clipboard.writeText(url).then(done,()=>toast(url));else toast(url)},
 reveal(x){ui.cur=x;ui.det=null;ui.sel=null;render(1)},
 nvt(x){const s=ui.sel||(ui.sel=[]);const i=s.indexOf(x);i<0?s.push(x):s.splice(i,1);render()},
 sel2(x){const s=ui.sel||(ui.sel=[]);const i=s.indexOf(x);if(i>=0)s.splice(i,1);else{if(s.length>=2)s.shift();s.push(x)}render()},
 ttsub(x){const s=[0,1,2].map(i=>clean(val('tt'+i),70));if(s.some(v=>!v))return toast(A('اكتب التلات حاجات','Write all three'));const l=[0,1,2].find(i=>($('#ttr'+i)||{}).checked);if(l==null)return toast(A('اختار أنهي واحدة الكدبة','Mark which one is the lie'));dispatch({t:'sub',k:App.S.g.c.k,v:{s,l},as:x})},
 qpsub(x){const v=clean(val('qpa'),70);if(!v)return toast(A('اكتب إجابتك الأول','Write your answer first'));dispatch({t:'sub',k:App.S.g.c.k,v,as:x})},
 hmsub(x){const v=clean(val('hma'),30);if(!v)return toast(A('اكتب إجابتك الأول','Write your answer first'));dispatch({t:'sub',k:App.S.g.c.k,v,as:x})},
 essub(x){const raw=String(val('esa')||'').replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[,،\s]/g,'').replace('٫','.');const v=parseFloat(raw);if(!isFinite(v))return toast(A('اكتب رقم','Type a number'));dispatch({t:'sub',k:App.S.g.c.k,v,as:x})},
 wksub(x){const v=clean(val('wka'),80);if(!v)return toast(A('اكتب إجابتك الأول','Write your answer first'));dispatch({t:'sub',k:App.S.g.c.k,v,as:x})},
 ltsub(x){const g=App.S&&App.S.g;if(!g||!g.c)return;const v=range(5).map(i=>clean(val('lt'+i),16));dispatch({t:'sub',k:g.c.k,v,as:x})},
 mfdet(x){ui.det=x;render()},
 peek(){ui.peek=!ui.peek;render()},
 lb(){ui.lb=!ui.lb;ui.rs=0;render(1)},
 rs(){ui.rs=1;render()},
 eg(){ui.eg=1;render()},
 lang(){App.lang=EL()?'ar':'en';LS.set('shilla.lang',App.lang);applyLang();render(1)},
 mute(){App.mute=!App.mute;LS.set('shilla.mute',App.mute);if(!App.mute)SFX.play('pop');render(1)},
 exit(){if(App.mode==='solo'){UI.soHome();return}if(!ui.ex){ui.ex=1;render();setTimeout(()=>{if(ui.ex){ui.ex=0;render()}},3000);return}leave()},
 exit2(){leave()},
 padd(){const v=clean(val('pn'),60);if(!v)return toast(A('اكتب العقاب الأول','Write the punishment first'));App.pun.push(v);App.pun=App.pun.slice(-15);LS.set('shilla.pun',App.pun);render(1,1);toast(A('اتضاف للعجلة ✓','Added to the wheel ✓'))},
 pdel(x){App.pun.splice(+x,1);LS.set('shilla.pun',App.pun);render(1)},
 pen(x,el){App.pen=x;document.querySelectorAll('.tools .sw').forEach(b=>b.classList.toggle('on',b===el))},
 clr(){const cv=$('#cv');if(!cv)return;const x=cv.getContext('2d');x.save();x.setTransform(1,0,0,1,0,0);x.fillStyle='#fffdf7';x.fillRect(0,0,cv.width,cv.height);x.restore()}
};

document.addEventListener('click',e=>{SFX.init();const j=e.target.closest('[data-j]');if(j&&!j.disabled){let a;try{a=JSON.parse(j.dataset.j)}catch(_){return}dispatch(a);return}
 const u=e.target.closest('[data-u]');if(u&&!u.disabled&&UI[u.dataset.u]){SFX.play('tap');UI[u.dataset.u](u.dataset.x,u)}});
document.addEventListener('keydown',e=>{if(e.key!=='Enter'||!e.target.id)return;const id=e.target.id;if(id.startsWith('soe'))UI.soEst();else if(id==='pn')UI.padd();else if(id==='rc'||(id==='rn'&&App.page==='rjn'))UI.rjn();else if(id==='rn')UI.rmk();else if(id==='hma'&&App.me!==undefined)UI.hmsub(App.mode==='local'?((App.S.g.c.need.find(i=>!(i in App.S.g.c.got)))):App.me);else if(id==='esa')UI.essub(App.mode==='local'?((App.S.g.c.need.find(i=>!(i in App.S.g.c.got)))):App.me)});

/* ---------- offline: service worker + install ---------- */
const INST={ev:null};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();INST.ev=e;if(!App.mode)render(1)});
window.addEventListener('appinstalled',()=>{INST.ev=null;toast(A('اتثبتت ✓ تقدر تفتحها من الشاشة الرئيسية','Installed ✓ open it from your home screen'));render(1)});
window.addEventListener('online',()=>render(1));
window.addEventListener('offline',()=>{render(1);if(App.mode!=='room')toast(A('النت فصل، بس تقدر تكمّل لعب عادي 👌','You\'re offline, but you can keep playing 👌'))});
if('serviceWorker' in navigator&&(location.protocol==='https:'||location.hostname==='localhost')){try{navigator.serviceWorker.register('sw.js').then(r=>{if(!LS.get('shilla.offok',false)){const done=()=>{LS.set('shilla.offok',true);toast(A('الموقع اتحفظ على موبايلك ✓ هيشتغل من غير نت','Saved on your phone ✓ it now works offline'))};const w=r.installing||r.waiting;if(r.active&&!w)LS.set('shilla.offok',true);else if(w)w.addEventListener('statechange',()=>{if(w.state==='activated')done()})}}).catch(()=>{})}catch(e){}}

/* ---------- boot: join links + rejoin after refresh ---------- */
{const r=(new URLSearchParams(location.search).get('r')||'').toUpperCase();
 if(/^[A-Z]{4}$/.test(r)){const h=LS.get('shilla.host',null),c=LS.get('shilla.client',null),fresh=x=>x&&x.code===r&&Date.now()-x.t<6*3600e3;
  if(fresh(h)&&h.S&&App.roomOK){App.code=r;enterRoom(r,true,h)}
  else if(fresh(c)&&App.nm&&App.roomOK){enterRoom(r,false)}
  else{App.jc=r;App.page='rjn'}}}
render(1);

